window.TAM_REVIEWS = {"product":114,"title":"더 클라우드 스킨 컨실러","asof":"2026.09.21","count":401,"avg":4.97,"dist":{"5":389,"4":12,"3":0,"2":0,"1":0},"items":[{"i":7252,"s":5,"t":"이거 왜 요즘 광고 안하죠..? 재구매하러 옵니다 전 이게 젤 좋은 것 같은데 탐뷰티","u":"네이버 페이 구매자","d":"2026-06-14 08:17:00","r":0,"p":["https://cdn.snapfit.co.kr/review/contents/stores/tambeauty/20260615/medium_4da1d2f02a0bb8ac34f486a865072b17.jpeg"]},{"i":2824,"s":5,"t":"트러블 흉터 때문에 스트레스였는데 커버력 진짜 짱짱함. 팁으로 얹어두고 좀 말랐을 때 스펀지로 두드리면 완벽 커버됨. 지속력도 좋아서 마스크 썼다 벗어도 멀쩡하네요.","u":"네이버 페이 구매자","d":"2026-01-06 23:54:00","r":0,"p":[]},{"i":2823,"s":5,"t":"탐뷰티 첨 들어봐서 반신반의하며 샀는데 의외의 꿀템 발견;; 21호 쿨톤인데 색상 화사하게 잘 빠졌고 무엇보다 스펀지로 블렌딩하니까 경계 안 지고 자연스러움. 커버력 필요한 분들 강추요👍🏻","u":"네이버 페이 구매자","d":"2026-01-06 23:39:00","r":0,"p":[]},{"i":2822,"s":5,"t":"건성이라 매트한 거 쓰면 눈가 주름 끼는데 이건 이름처럼 가볍게 발리면서 안 떠요. 다크서클 푸른기 싹 잡아주는데 두껍지 않아서 좋음. 얇게 레이어링 하면 잡티 순삭 가능.","u":"네이버 페이 구매자","d":"2026-01-06 21:40:00","r":0,"p":[]},{"i":2821,"s":5,"t":"파워 지성이라 컨실러 써도 금방 날아가는데 이건 고정력 미쳤어요. 아침에 바르고 나가서 수정 화장 거의 안 해도 됨.. 땀 흘려도 안 뭉치고 얇게 밀착돼서 요물임.","u":"네이버 페이 구매자","d":"2026-01-06 21:30:00","r":0,"p":[]},{"i":2820,"s":5,"t":"손에 묻히기 싫어서 샀는데 스펀지 팁 내장된 게 신의 한 수네요. 걍 콕콕 찍고 뒷부분으로 두드리면 끝이라 진짜 편해요. 다크서클 퀭한 편인데 커버력도 상타치임. 재구매 의사 있음.","u":"네이버 페이 구매자","d":"2026-01-06 21:12:00","r":0,"p":[]},{"i":2819,"s":5,"t":"눈가 주름 끼임 없이 다크서클 커버되는 컨실러 찾다가 정착했습니다. 팁으로 콕 찍고 뒤에 달린 스펀지로 펴주면 블렌딩이 진짜 쉬워요. 아침에 바르고 나가서 저녁까지 다크닝 없이 유지되는 거 보고 감동받음 ㅠㅠ 다 쓰면 또 살 거예요. 부끄러워서 사진은 손으로 대체합니다.....ㅎㅎㅎ","u":"네이버 페이 구매자","d":"2026-01-06 20:57:00","r":0,"p":["https://cdn.snapfit.co.kr/review/contents/stores/tambeauty/20260511/medium_672f712996700100eb93c18756d6c8df.jpeg","https://cdn.snapfit.co.kr/review/contents/stores/tambeauty/20260511/medium_48e25641ba11b0b8d35cf4da97232737.jpeg"]},{"i":2818,"s":5,"t":"커버력 좋다는 후기 보고 샀는데 진짜네요. 붉은 기랑 트러블 자국 깔끔하게 가려집니다. 다만 픽싱력이 강해서 건성이신 분들은 기초 탄탄하게 하고 올리시는 걸 추천드려요! 스펀지로 펴 바르니까 경계 안 지고 자연스러워서 똥손도 쓰기 쉬워요.","u":"네이버 페이 구매자","d":"2026-01-06 20:30:00","r":0,"p":[]},{"i":2817,"s":5,"t":"탐뷰티 베이스 맛집이네요. 수정 화장용으로 샀는데 휴대가 간편해서 요즘 가방에 이거 하나만 넣고 다녀요. 커버력은 높은데 두껍게 안 발리고 피부에 얇게 촥 붙는 느낌? 땀 많이 흘린 날에도 안 지워져서 유지력 인정합니다.","u":"네이버 페이 구매자","d":"2026-01-06 17:31:00","r":0,"p":[]},{"i":2816,"s":5,"t":"지성 피부라 컨실러 쓰면 시간 지날수록 금방 뜨거나 지워지는데 이건 밀착력이 진짜 좋네요. 이름처럼 가볍게 발리는데 잡티는 싹 가려줘요. 내장된 스펀지가 생각보다 쫀쫀해서 따로 퍼프 안 들고 다녀도 돼서 좋아요 ㅎㅎ 재구매 의사 있습니다.","u":"네이버 페이 구매자","d":"2026-01-06 16:22:00","r":0,"p":[]},{"i":2815,"s":5,"t":"스펀지 팁이 달려있어서 손에 컨실러 안 묻히고 톡톡 두드리면 끝이라 너무 편해요. 다크서클이 심한 편인데 얇게 발리면서도 커버가 확실하게 돼서 놀랐습니다. 픽싱이 빠른 편이라 바르고 바로 내장 스펀지로 블렌딩해주는 게 좋을 것 같아요. 지속력도 좋아서 여름에 쓰기 딱입니다.","u":"네이버 페이 구매자","d":"2026-01-06 15:40:00","r":0,"p":[]},{"i":2814,"s":5,"t":"전 후 차이 보이시나요 ..... 너무 좋네요 선물용으로 몇 개 더 주문하러 온 겸 리뷰 남겨요 ㅎㅎ","u":"네이버 페이 구매자","d":"2026-01-06 15:32:00","r":0,"p":["https://cdn.snapfit.co.kr/review/contents/stores/tambeauty/20260511/medium_416cd8c3c8a7db1851f54cbbd2d64e35.jpeg","https://cdn.snapfit.co.kr/review/contents/stores/tambeauty/20260511/medium_008754e1a9b78a65ded785f8656c4710.jpeg"]},{"i":2813,"s":5,"t":"트러블 자국 때문에 스트레스였는데 이거 쓰고 광명 찾음.. 붉은기 커버 확실하고 무엇보다 땀 흘려도 잘 안 지워져서 운동할 때도 바름. 21호 쓰는데 컬러 자연스럽게 잘 맞아요.","u":"네이버 페이 구매자","d":"2026-01-06 14:58:00","r":0,"p":[]},{"i":2812,"s":5,"t":"매장에서 손등에 발라보고 밀착력 좋아서 바로 집어옴. 얇게 발리는데 커버력은 중상 이상이라 답답하지 않음. 브러쉬 따로 안 챙겨도 되니까 수정용으로 들고 다니기 딱 좋음.","u":"네이버 페이 구매자","d":"2026-01-06 14:10:00","r":0,"p":[]},{"i":2811,"s":5,"t":"지성이라 오후 되면 베이스 다 무너지는데 이건 픽싱이 빨라서 오래감. 잡티 위에 찍고 스펀지로 펴주면 감쪽같이 사라짐. 세일할 때 쟁여둬야겠어요.","u":"네이버 페이 구매자","d":"2026-01-06 14:01:00","r":0,"p":[]},{"i":2810,"s":5,"t":"다크서클 커버용으로 샀는데 내장 스펀지가 진짜 편해요. 손에 안 묻히고 톡톡 두드리면 끝나서 바쁜 아침에 최고임. 건성인데 눈가 끼임도 거의 없어서 만족합니다.","u":"네이버 페이 구매자","d":"2026-01-06 12:15:00","r":0,"p":[]},{"i":2809,"s":5,"t":"아침에 바쁠 때 이거 하나면 베이스 뚝딱이에요. 브러쉬 따로 꺼내기 귀찮은 분들한테 강추. 스펀지로 펴 바르니까 자국도 안 남고 블렌딩 진짜 자연스럽게 잘 돼요. 색상은 살짝 밝게 나온 편이니 참고하세요~","u":"네이버 페이 구매자","d":"2026-01-06 12:11:00","r":0,"p":[]},{"i":2808,"s":5,"t":"날씨 더워지면서 베이스 다 무너져서 롱웨어 찾다가 구매했어요. 확실히 땀나도 잘 안 지워지고 고정력이 좋네요. 파데 대신 이것만 잡티 부위에 얇게 깔고 나가도 될 정도? 요철 부각도 거의 없어서 만족합니다. 올영 세일할 때 쟁여둘 예정.","u":"네이버 페이 구매자","d":"2026-01-06 12:05:00","r":0,"p":[]},{"i":2807,"s":5,"t":"다크서클이 무릎까지 내려오는 사람인데 이거 물건이네요.. 컨실러 유목민 생활 청산할 듯. 두껍게 안 올라가는데 커버는 확실하게 돼요. 다만 스펀지 일체형이라 위생 관리를 어떻게 해야 할지 살짝 고민되긴 하는데 편해서 계속 쓸 것 같아요. 밀착력 진짜 굿.","u":"네이버 페이 구매자","d":"2026-01-06 11:18:00","r":0,"p":[]},{"i":2806,"s":5,"t":"21호 쿨톤인데 컬러가 누르렁하지 않고 예쁘게 뽑혔어요. 건성이라 너무 매트하면 눈가 갈라지는데 이건 이름처럼 가볍게 올라가는 느낌? 근데 스펀지 팁이라 양 조절은 필수예요. 살짝만 짜서 펴 바르면 피부 표현 진짜 예쁘게 됨. 커버력은 중상 정도?","u":"네이버 페이 구매자","d":"2026-01-06 09:46:00","r":0,"p":[]},{"i":2805,"s":5,"t":"탐뷰티 처음 들어봐서 반신반의하면서 샀는데 기대 이상이에요. 일단 스펀지 팁 달려있는 게 신의 한 수... 손에 안 묻히고 톡톡 두드리면 끝이라 아침에 진짜 편해요. 지성이라 오후 되면 코 옆 끼임 심한데 이건 픽싱이 빨라서 그런지 지속력도 괜찮네요. 다크서클 가리기 딱 좋아요.","u":"네이버 페이 구매자","d":"2026-01-06 07:26:00","r":0,"p":[]},{"i":2804,"s":5,"t":"피부에 올렸을 때 텁텁한 느낌 없이 얇게 밀착돼서 놀랐어요. 스펀지로 펴 바르니까 손자국도 안 남고 모공 커버도 꽤 잘 됩니다. 홍조랑 잡티 커버 확실하고 마스크 써도 잘 안 묻어나서 좋아요.","u":"네이버 페이 구매자","d":"2026-01-06 07:24:00","r":0,"p":[]},{"i":2803,"s":5,"t":"광고 보고 반신반의하면서 샀는데 인생템 등극이요. 스펀지 팁이 생각보다 퀄리티가 좋아서 경계 지는 거 없이 자연스럽게 블렌딩돼요. 똥손도 쓰기 쉬울 듯. 파데 대신 이거 하나로 베이스 끝낼 때도 많아요👍","u":"네이버 페이 구매자","d":"2026-01-06 06:12:00","r":0,"p":[]},{"i":2802,"s":5,"t":"수부지 피부인데 오후에 유분기 올라와도 더럽게 무너지지 않아서 합격입니다. 땀 많이 흘린 날에도 수정 화장 거의 안 했어요. 스펀지로 두드리니까 밀착이 쫀쫀하게 잘 되는 느낌? 지속력 중요하게 생각하시면 꼭 사세요.","u":"네이버 페이 구매자","d":"2026-01-06 03:17:00","r":0,"p":[]},{"i":2801,"s":5,"t":"눈가 피부가 얇아서 컨실러 잘못 쓰면 주름에 다 끼는데, 이건 촉촉하게 발리면서 픽싱되면 딱 고정되네요. 다크서클이 심한 편인데 붉은기 없이 깔끔하게 커버돼서 만족합니다. 건성인 분들한테도 추천해요.","u":"네이버 페이 구매자","d":"2026-01-06 01:47:00","r":0,"p":[]},{"i":2800,"s":5,"t":"스펀지 팁 내장된 게 진짜 신의 한 수... 손에 뭐 묻는 거 딱 질색인데 그냥 슥 그어서 톡톡 두드리면 끝이라 너무 편해요. 아침에 바쁠 때 시간 단축 제대로 됩니다. 커버력도 기대 이상이라 웬만한 잡티는 다 가려져요.","u":"네이버 페이 구매자","d":"2026-01-06 00:33:00","r":0,"p":[]},{"i":2799,"s":5,"t":"유튜브 보고 샀는데 기대 이상이에요 얇게 발리는데 커버력은 확실함 스펀지 따로 안 챙겨도 돼서 아침에 화장 시간 줄었어요 다 쓰면 또 살 예정","u":"네이버 페이 구매자","d":"2026-01-05 23:37:00","r":0,"p":[]},{"i":2798,"s":5,"t":"건성이라 매트할까봐 걱정했는데 생각보다 건조하지 않아요 눈가 주름 끼임도 적은 편이고 무엇보다 스펀지로 펴바르니까 손에 안 묻는 게 최고 장점 ㅋㅋ 여행갈 때 이거 하나만 챙겨도 될 듯","u":"네이버 페이 구매자","d":"2026-01-05 22:06:00","r":0,"p":[]},{"i":2797,"s":5,"t":"트러블 자국 많은데 웬만한건 다 가려짐 ㄱㅊ 근데 양조절 잘해야할듯 첨에 너무 팍 나와서 당황했는데 익숙해지니까 편함 지속력도 나쁘지않음","u":"네이버 페이 구매자","d":"2026-01-05 19:15:00","r":0,"p":[]},{"i":2796,"s":5,"t":"수부지라 오후되면 화장 다 무너지는데 이건 픽싱력 찐이네요 땀 흘려도 그대로임; 스펀지로 블렌딩하니까 자국도 안 남고 밀착 잘돼서 만족. 여름에 쓰기 딱 좋을 듯","u":"네이버 페이 구매자","d":"2026-01-05 15:38:00","r":0,"p":[]},{"i":2795,"s":5,"t":"다크서클 땜에 컨실러 유목민이었는데 이거 물건임.. 스펀지팁 달려있어서 걍 톡톡 두드리면 끝이라 편해요. 커버력은 좋은데 두껍게 안 발려서 좋음 재구매 의사 있음","u":"네이버 페이 구매자","d":"2026-01-05 15:21:00","r":0,"p":[]},{"i":2794,"s":5,"t":"픽싱되는 속도가 빨라서 바르고 바로 블렌딩 해줘야 해요. 그만큼 고정력은 진짜 짱짱함. 마스크 써도 거의 안 묻어나서 요즘 매일 쓰는 중 ㅎ","u":"네이버 페이 구매자","d":"2026-01-05 14:40:00","r":0,"p":[]},{"i":2793,"s":5,"t":"다크서클이 심해서 컨실러 유목민이었는데 여기에 눕습니다... 이름처럼 가볍게 올라가는데 커버는 확실하게 돼요. 스펀지로 펴 바르니까 경계도 안 지고 자연스러움. 근데 양 조절은 좀 신경 써야 할 듯? 너무 많이 나오면 뭉칠 수 있어요.","u":"네이버 페이 구매자","d":"2026-01-05 14:18:00","r":0,"p":[]},{"i":2792,"s":5,"t":"배송 하루 만에 옴 ㄷㄷ 스펀지 달려있어서 슥슥 바르기 좋아요. 파데 대신 이걸로 화장 끝냄. 가볍게 발려서 답답한 거 싫어하는 분들 추천!!","u":"네이버 페이 구매자","d":"2026-01-05 13:09:00","r":0,"p":[]},{"i":2791,"s":5,"t":"수부지인데 이거 밀착력 미쳤네요.. 탐뷰티 처음 들어봐서 반신반의하면서 샀는데 기대 이상임. 얇게 발리는데 커버력은 중상? 정도 되고 무엇보다 땀 흘려도 안 지워져서 좋음. 스펀지는 좀 자주 빨아야 할 거 같긴 한데 편하긴 함.","u":"네이버 페이 구매자","d":"2026-01-05 12:45:00","r":0,"p":[]},{"i":2790,"s":5,"t":"와 진짜 대박 편해요;; 스펀지 팁 달려있는 게 신의 한 수인 듯. 손에 안 묻히고 톡톡 두드리면 다크서클 순삭됨. 지속력도 꽤 길어서 아침에 바르고 나가면 저녁까지 멀쩡해요. 재구매각.","u":"네이버 페이 구매자","d":"2026-01-05 12:34:00","r":0,"p":[]},{"i":2789,"s":5,"t":"와 이거 진짜 요물임.. 여드름 흉터 때문에 컨실러 유목민 생활 오래 했는데 당분간 여기에 정착합니다. 팁으로 콕 찍고 뒤에 달린 스펀지로 경계 풀어주면 티 안 나게 싹 가려져요. 땀 흘려도 안 지워지는 거 보고 놀랐음. 친구들한테도 영업 중이에요.","u":"네이버 페이 구매자","d":"2026-01-05 12:24:00","r":0,"p":[]},{"i":2788,"s":5,"t":"유튜브 광고 보고 혹해서 샀는데 의외로 물건이네요? 보통 커버력 좋으면 엄청 두껍게 발리는데 이건 얇게 찹 밀착되는 느낌이라 좋아요. 내장 스펀지가 있어서 손에 안 묻히고 수정 화장 할 수 있는 게 제일 맘에 듭니다 ㅎ 다만 스펀지 팁 관리는 좀 신경 써야 할 거 같아요.","u":"네이버 페이 구매자","d":"2026-01-05 09:45:00","r":0,"p":[]},{"i":2787,"s":5,"t":"커버력은 진짜 인정. 잡티 싹 가려짐. 근데 제가 워낙 악건성이라 그런지 눈 밑은 시간 지나니까 살짝 건조해지는 느낌이 있었음. 기초 탄탄하게 하고 바르면 괜찮을 것 같긴 한데 건성분들은 테스트 해보고 사세요. 지성분들한테는 인생템 될 듯.","u":"네이버 페이 구매자","d":"2026-01-05 09:26:00","r":0,"p":[]},{"i":2786,"s":5,"t":"수부지 피부입니다. 오후만 되면 유분 올라와서 베이스 다 무너지는데 이거 지속력 찐이네요. 이름처럼 가볍게 발리는데 커버는 확실하게 됨. 스펀지로 두드리니까 블렌딩도 자연스럽고 주름 끼임도 거의 없어요. 여름에 쓰기 딱 좋을 듯. 재구매 의사 있습니다.","u":"네이버 페이 구매자","d":"2026-01-05 08:37:00","r":0,"p":[]},{"i":2785,"s":5,"t":"탐뷰티 처음 들어보는 브랜드인데 스펀지팁 내장되어 있대서 궁금해서 사봤어요. 아침에 바쁜데 브러쉬 따로 안 찾아도 되고 그냥 슥 긋고 톡톡 두드리면 끝나니까 진짜 편하네요. 제가 다크서클이 진짜 심한데 커버력도 기대 이상이에요. 밀착력도 좋아서 마스크에 별로 안 묻어남.","u":"네이버 페이 구매자","d":"2026-01-05 07:17:00","r":0,"p":[]},{"i":2784,"s":5,"t":"탐뷰티 처음 써보는데 기대 이상이네요? 색상이 너무 칙칙하지 않고 피부 표현이 예쁘게 돼요. 무엇보다 스펀지로 두드릴수록 밀착력이 높아져서 원래 피부 좋은 것처럼 보임. 재구매 의사 있어요.","u":"네이버 페이 구매자","d":"2026-01-05 06:47:00","r":0,"p":[]},{"i":2783,"s":5,"t":"요즘 파데프리 하는데 이거 하나로 잡티만 톡톡 가리고 나가요. 내장 스펀지가 쫀쫀해서 경계 안 지고 블렌딩이 진짜 자연스럽게 됨! 도구 따로 챙기기 귀찮은 분들이나 곰손들도 쉽게 쓸 수 있을 것 같아요.","u":"네이버 페이 구매자","d":"2026-01-05 04:35:00","r":0,"p":[]},{"i":2782,"s":5,"t":"오후만 되면 유분 폭발하는 지성 피부인데 이거 지속력 미쳤네요. 땀 좀 흘려도 거의 안 지워지고 피부에 딱 붙어있어요. 잡티 커버도 확실한데 답답한 느낌 없어서 여름까지 쭉 쓸 듯합니다.","u":"네이버 페이 구매자","d":"2026-01-05 02:15:00","r":0,"p":[]},{"i":2781,"s":5,"t":"다크서클이 심해서 컨실러 유목민이었는데 여기에 정착합니다. 스펀지로 블렌딩하니까 눈가 주름 끼임 없이 깔끔하게 가려져요. 건성인데도 시간 지나도 들뜸 없이 하루 종일 유지되는 거 보고 감동받음 ㅠㅠ","u":"네이버 페이 구매자","d":"2026-01-05 02:12:00","r":0,"p":[]},{"i":2780,"s":5,"t":"팁이 달려있는 게 진짜 신의 한 수... 손에 묻힐 필요 없이 톡톡 두드리면 끝나서 너무 편해요. 보통 이런 일체형은 좀 두껍게 발리는데 이건 얇게 밀착돼서 놀랐음. 아침에 시간 없을 때 퀵 메이크업용으로 최고입니다.","u":"네이버 페이 구매자","d":"2026-01-05 02:09:00","r":0,"p":[]},{"i":2779,"s":5,"t":"21호 쿨톤인데 색상 화사하게 잘 뽑혔어요. 보통 컨실러들 너무 노랗게 나와서 둥둥 뜨는데 이건 딱 예쁜 상아색이라 다크서클이랑 잡티 자연스럽게 커버됨. 스펀지로 팡팡 두드리면 결 자국도 안 남고 꿀템 인정.","u":"네이버 페이 구매자","d":"2026-01-05 02:08:00","r":0,"p":[]},{"i":2778,"s":5,"t":"탐뷰티? 처음 들어보는 브랜드라 반신반의하면서 샀는데 기대 이상이네요. 고가 브랜드 컨실러랑 비교해도 손색없음. 얇게 발리는데 커버는 확실해서 피부 표현이 예쁘게 돼요. 스펀지 팁 위생 관리만 잘하면 될 듯.","u":"네이버 페이 구매자","d":"2026-01-05 01:04:00","r":0,"p":[]},{"i":2777,"s":5,"t":"땀 많이 흘리는 체질이라 오후만 되면 베이스 다 무너지는데 이건 진짜 짱짱하게 버티네요. 잡티 위에 콕 찍고 내장 스펀지로 블렌딩하면 감쪽같음. 지속력 미쳤어요... 세일할 때 쟁여두시길.","u":"네이버 페이 구매자","d":"2026-01-04 23:27:00","r":0,"p":[]},{"i":2776,"s":5,"t":"건성이라 눈가 주름 끼임 심해서 컨실러 유목민이었는데 여기에 정착할 듯요. 이름처럼 가볍게 발리는데 커버력은 짱짱함;; 다크서클 푸른기 싹 가려줘서 요즘 이것만 씁니다. 여름에도 잘 버틸 것 같은 롱웨어 재질임.","u":"네이버 페이 구매자","d":"2026-01-04 22:51:00","r":0,"p":[]},{"i":2775,"s":5,"t":"스펀지 팁 달려있는 게 진짜 신의 한 수... 손에 뭐 묻히기 싫은 날 그냥 톡톡 찍고 뒤에 달린 스펀지로 펴 바르면 끝나서 너무 편해요. 커버력도 중상 정도 되고 무엇보다 밀착력이 좋아서 시간 지나도 뜨지 않네요. 재구매 의사 있음.","u":"네이버 페이 구매자","d":"2026-01-04 19:49:00","r":0,"p":[]},{"i":2774,"s":5,"t":"친구가 추천해서 샀는데 진짜 편하네용 파우치에 쏙 들어가는 사이즈라 수정화장 할 때 최고에오.. 스펀지가 쫀쫀해서 피부에 착 붙는 느낌? 다크서클 커버도 잘되고 뭉침 없어서 너모 조아요 내돈내산 후기입니당","u":"네이버 페이 구매자","d":"2026-01-04 19:38:00","r":0,"p":[]},{"i":2773,"s":5,"t":"트러블 흉터 때문에 스트레스였는데 이거 커버력 머선일.. 탐뷰티 처음 써보는데 기대 이상이에여 스펀지 팁이 내장돼있어서 따로 브러쉬 안 써도 되니까 위생적이고 블렌딩도 짱 쉬움 21호 피부인데 색상도 찰떡콩떡임다","u":"네이버 페이 구매자","d":"2026-01-04 18:15:00","r":0,"p":[]},{"i":2772,"s":5,"t":"다크서클이 심해서 컨실러 유목민이었는데 드디어 정착템 찾았어오.. 보통 커버력 좋으면 뻑뻑한데 이건 촉촉하게 발리면서 커버는 다 됨! 스펀지로 두드리니까 주름 끼임도 없고 얇게 올라가서 맘에 들어요 굿굿","u":"네이버 페이 구매자","d":"2026-01-04 13:55:00","r":0,"p":[]},{"i":2771,"s":5,"t":"지성피부라 오후만 되면 베이스 다 무너지는데 이건 지속력 진짜 대박이네유.. 땀 흘려도 안 지워지고 짱짱하게 붙어있어요 ☁️ 밀착력 좋아서 마스크에도 잘 안 묻어나고 요새 이것만 씀","u":"네이버 페이 구매자","d":"2026-01-04 13:46:00","r":0,"p":[]},{"i":2770,"s":5,"t":"와 이거 진짜 물건이네요.. 스펀지팁 달려있어서 손에 안 묻히고 슥슥 바르기 넘 편해요ㅠㅠ 아침에 바쁠 때 톡톡 찍고 문지르면 끝이라 출근용으로 딱임.. 커버력도 좋아서 다크서클 싹 가려져요 재구매 의사 있음!","u":"네이버 페이 구매자","d":"2026-01-04 12:12:00","r":0,"p":[]},{"i":2769,"s":5,"t":"이름처럼 가볍게 올라가는데 커버력은 확실하네요. 보통 커버력 좋으면 텁텁하기 마련인데 이건 얇게 밀착돼서 피부가 답답하지 않아요. 마스크 썼다 벗어도 찍힘 거의 없어서 요즘 정착했습니다.","u":"네이버 페이 구매자","d":"2026-01-04 11:42:00","r":0,"p":[]},{"i":2768,"s":5,"t":"탐뷰티 처음 들어보는 브랜드라 반신반의하면서 샀는데 기대 이상이에요. 내장 스펀지가 진짜 물건이네요.. 잡티 위에 콕 찍고 펴 바르면 끝이라 너무 간편해요. 다 쓰면 또 살 것 같아요 :)","u":"네이버 페이 구매자","d":"2026-01-04 11:22:00","r":0,"p":[]},{"i":2767,"s":5,"t":"21호 쿨톤인데 컬러가 너무 노랗지 않고 화사해서 좋았어요. 눈 밑에 푸르딩딩한 다크서클 싹 가려줍니다. 다만 스펀지로 너무 세게 문지르면 베이스가 밀릴 수 있으니 힘 빼고 톡톡 두드리는 게 꿀팁이에요.","u":"네이버 페이 구매자","d":"2026-01-04 08:48:00","r":0,"p":[]},{"i":2766,"s":5,"t":"지성이라 오후만 되면 유분 폭발해서 컨실러 다 지워지는데 이건 짱짱하네요. 땀 많이 흘린 날에도 거의 그대로 붙어있었어요. 스펀지로 톡톡 두드리면 블렌딩도 쉬워서 곰손인 분들께 추천해요.","u":"네이버 페이 구매자","d":"2026-01-04 08:05:00","r":0,"p":[]},{"i":2765,"s":5,"t":"스펀지 팁이 붙어있어서 진짜 편해요. 아침에 바쁜데 손에 파데 묻히기 싫을 때 딱입니다. 다크서클 커버용으로 샀는데 눈가 주름 끼임 없이 얇게 발리네요. 지속력도 꽤 괜찮아서 점심 먹고 수정 화장 안 해도 될 정도예요.","u":"네이버 페이 구매자","d":"2026-01-04 05:43:00","r":0,"p":[]},{"i":2764,"s":5,"t":"커버부터 블렌딩까지 한번에 된다길래 똥손이라 질러봄.. 확실히 손으로 펴바르는 것보다 훨씬 자연스럽게 커버됨! 땀에도 강하다니 다가오는 여름까지 쭉 쓸듯합니다 재구매 의사 잇음","u":"네이버 페이 구매자","d":"2026-01-04 04:57:00","r":0,"p":[]},{"i":2763,"s":5,"t":"인스타 보고 혹해서 샀는데 생각보다 물건이네여;; 스펀지가 내장되어 있어서 브러쉬 따로 안 챙겨도 돼서 파우치 줄이기 딱임. 여행갈 때 챙겨가려구요. 잡티 커버는 중상 정도? 지속력은 ㄱㅊ은듯.","u":"네이버 페이 구매자","d":"2026-01-04 04:36:00","r":0,"p":[]},{"i":2762,"s":5,"t":"잡티보단 다크서클 가리려고 샀는데 촉촉하게 발려서 눈가 주름 끼임 없어서 좋아요 ㅠㅠ 건성 김미연인데 들뜨는 거 없이 착붙임. 다크닝도 별로 없어서 하루종일 화사함 유지 가능ㅇㅇ 쿨톤 21호한테 컬러 딱임","u":"네이버 페이 구매자","d":"2026-01-04 04:24:00","r":0,"p":[]},{"i":2761,"s":5,"t":"지성이라 오후 되면 컨실러 다 녹아서 걱정했는데 이건 롱웨어라 그런지 짱짱하게 버티네요. 스펀지로 두드리니까 모공도 어느 정도 메워지는 느낌? 근데 첨에 양 조절 잘해야 할 듯 푹 찍으면 두껍게 올라감 주의.","u":"네이버 페이 구매자","d":"2026-01-04 01:22:00","r":0,"p":[]},{"i":2760,"s":5,"t":"스펀지 팁 있어서 손에 안 묻히고 톡톡 두드리면 끝이라 너무 편해요ㅋㅋ 아침에 출근 준비할 때 시간 단축 꿀템임. 커버력도 기대 이상이고 다크서클 퀭한 거 싹 가려짐.. 밀착력 좋아서 픽서 안 뿌려도 오래 가네용","u":"네이버 페이 구매자","d":"2026-01-03 23:35:00","r":0,"p":[]},{"i":2759,"s":5,"t":"탐뷰티 처음이라 반신반의하면서 샀는데 기대 이상이에요. 컨실러 붓 따로 챙기기 귀찮았는데 이거 하나 들고 다니면 수정 화장까지 해결됨. 내돈내산 아깝지 않음!!","u":"네이버 페이 구매자","d":"2026-01-03 21:40:00","r":0,"p":[]},{"i":2758,"s":5,"t":"이름값 하네요 진짜 가벼움. 보통 커버력 높으면 텁텁하기 마련인데 이건 얇게 발려서 피부 좋아 보여요. 내장 스펀지로 두드리니까 브러쉬 자국도 안 남고 모공 끼임도 없음 굿","u":"네이버 페이 구매자","d":"2026-01-03 19:46:00","r":0,"p":[]},{"i":2757,"s":5,"t":"파워 지성이라 오후만 되면 코 옆이랑 다크닝 장난 아닌데 이건 진짜 짱짱하네요. 유분기 올라와도 더럽게 무너지는 게 아니라 예쁘게 광나는 느낌? 땀 나도 그대로라 여름까지 쭉 쓸 듯.","u":"네이버 페이 구매자","d":"2026-01-03 18:47:00","r":0,"p":[]},{"i":2756,"s":5,"t":"다크서클 부자라 컨실러 유목민이었는데 여기에 눕습니다.. 커버력 무슨 일? 두껍게 발리는 게 아니라 얇게 착 붙어서 답답하지도 않아요. 건성인데 눈가 주름 끼임 없는 게 제일 맘에 듬.","u":"네이버 페이 구매자","d":"2026-01-03 17:42:00","r":0,"p":[]},{"i":2755,"s":5,"t":"아니 이거 왜 이제 알았음?? 스펀지 팁 달린 게 진짜 신의 한 수;; 손에 묻히기 싫어서 샀는데 블렌딩 그냥 끝나요. 바쁜 아침에 걍 톡톡하면 베이스 뚝딱이라 삶의 질 올라감.","u":"네이버 페이 구매자","d":"2026-01-03 09:49:00","r":0,"p":[]},{"i":2754,"s":5,"t":"커버력은 진짜 인정! 홍조랑 흉터 싹 가려집니다. 다만 스펀지 팁이라 위생 관리는 좀 신경 써야 할 것 같아요. 그래도 따로 브러쉬 안 들고 다녀도 돼서 수정 화장용으로 파우치에 넣고 다니기엔 최고예요.","u":"네이버 페이 구매자","d":"2026-01-03 08:01:00","r":0,"p":[]},{"i":2753,"s":5,"t":"컬러가 되게 상아빛으로 예쁘게 나왔어요. 21호 쓰는데 화사하게 잘 맞아요. 무엇보다 스펀지로 바르니까 밀착이 촥 되는 느낌? 두껍게 안 올라가서 피부 답답한 거 싫어하시는 분들한테 추천드려요 👍","u":"네이버 페이 구매자","d":"2026-01-03 07:55:00","r":0,"p":[]},{"i":2752,"s":5,"t":"다크서클이 심해서 웬만한 컨실러 다 써봤는데 탐뷰티꺼 물건이네요. 내장 스펀지로 톡톡 두드려주니까 얇게 발리면서 커버는 확실해요! 주름 끼임도 거의 없어서 눈가에 쓰기 딱 좋습니다 굿굿.","u":"네이버 페이 구매자","d":"2026-01-03 06:55:00","r":0,"p":[]},{"i":2751,"s":5,"t":"수부지 피부라 오후만 되면 다크닝 오고 무너지는데 이건 지속력 미쳤어요.. 땀이랑 유분에 강하다더니 진짜 저녁까지 짱짱하게 버티네요. 파데 안 하고 이거로만 베이스 해도 될 정도로 밀착력 좋습니다. 여름 컨실러로 정착할 듯.","u":"네이버 페이 구매자","d":"2026-01-03 05:36:00","r":0,"p":[]},{"i":2750,"s":5,"t":"스펀지 팁이 달려있어서 진짜 편해요. 손에 뭐 묻히기 싫을 때 딱입니다. 그냥 콕 찍고 쓱쓱 문지르면 블렌딩 끝이라 아침에 시간 단축돼요. 커버력도 기대 이상이라 잡티 싹 가려지네요. 다 쓰면 재구매 의사 있어요.","u":"네이버 페이 구매자","d":"2026-01-03 04:28:00","r":0,"p":[]},{"i":2749,"s":5,"t":"인스타 광고 보고 반신반의하면서 샀는데 기대 이상이에요.\n파데 프리 메이크업 할 때 잡티 부분에만 이거 쓱 바르고 나가면 피부 표현 완전 깔끔하게 돼요.\n마스크 써도 잘 안 묻어나고 픽싱이 빨라서 좋네요. 다 쓰면 또 살 거예요.","u":"네이버 페이 구매자","d":"2026-01-03 02:09:00","r":0,"p":[]},{"i":2748,"s":5,"t":"여드름 흉터 가리려고 샀는데 커버력 미쳤어요..\n붉은기 싹 가려주는데 텁텁한 느낌이 아니라 피부 좋아 보이는 느낌?\n스펀지가 내장되어 있어서 손에 묻힐 필요 없는 게 진짜 편해요.\n위생적인지는 좀 더 써봐야 알겠지만 일단 사용감은 합격입니다👍","u":"네이버 페이 구매자","d":"2026-01-03 00:24:00","r":0,"p":[]},{"i":2747,"s":5,"t":"지성이라 오후만 되면 베이스 다 무너지는데 이건 지속력 대박이네요.\n땀 흘려도 그대로 남아있어요. 스펀지로 톡톡 두드려주면 블렌딩도 자연스럽고 자국 안 남아서 초보자가 쓰기 딱 좋은 듯.\n다만 양 조절은 필수예요 소량으로도 커버 충분함.","u":"네이버 페이 구매자","d":"2026-01-03 00:22:00","r":0,"p":[]},{"i":2746,"s":5,"t":"다크서클이 심해서 웬만한 컨실러는 다 써봤는데 탐뷰티 정착할 것 같아요.\n보통 커버력 좋으면 엄청 뻑뻑해서 눈가 주름에 끼는데 이건 이름처럼 구름같이? 가볍게 발리면서 밀착이 착 돼요.\n건성인데도 갈라짐 없이 오래가서 신기하네요. 재구매 의사 있어요!","u":"네이버 페이 구매자","d":"2026-01-03 00:02:00","r":0,"p":[]},{"i":2745,"s":5,"t":"이거 진짜 물건이네요. 뒤에 달린 스펀지 팁이 신의 한 수예요..\n따로 브러쉬나 퍼프 안 챙겨도 돼서 밖에서 수정할 때 너무 편해요.\n다크서클 가릴 때 콕콕 찍고 내장 팁으로 쓱쓱 문지르면 끝이라 아침에 시간 단축 짱임.\n커버력도 좋은데 두껍지 않게 올라가서 맘에 듭니다.","u":"네이버 페이 구매자","d":"2026-01-02 23:39:00","r":0,"p":[]},{"i":2744,"s":5,"t":"컨실러 유목민 드디어 정착합니다.. 탐뷰티 처음 들어보는 브랜드라 반신반의하면서 샀는데 밀착력 미쳤음. 스펀지로 톡톡 두드리면 모공 끼임 없이 깔끔하게 발려요. 내돈내산 아깝지 않음!","u":"네이버 페이 구매자","d":"2026-01-02 23:19:00","r":0,"p":[]},{"i":2743,"s":5,"t":"헬스장 갈 때 베이스 안 하고 이거 하나로 잡티만 가리고 가는데 땀 흘려도 안 지워져서 놀랐음;; 지속력 진짜 짱짱함. 21호 쓰는데 컬러도 화사하고 예뻐요. 여름에 더 잘 쓸 듯.","u":"네이버 페이 구매자","d":"2026-01-02 22:42:00","r":0,"p":[]},{"i":2742,"s":5,"t":"유튜브 보고 영업 당해서 샀는데 기대 이상이에요! 잡티 커버보다는 톤 보정에 더 좋은 느낌. 근데 스펀지가 내용물을 좀 많이 먹는 것 같아서 아까움.. 그래도 들고 다니면서 수정 화장하기엔 편해요.","u":"네이버 페이 구매자","d":"2026-01-02 22:38:00","r":0,"p":[]},{"i":2741,"s":5,"t":"다크서클이 심해서 샀는데 얇게 발리면서 커버 잘 되네요. 보통 컨실러는 두껍게 올라가서 갈라지는데 이건 착 붙는 느낌? 스펀지로 두드리니까 블렌딩도 자연스럽게 돼요. 굿.","u":"네이버 페이 구매자","d":"2026-01-02 22:33:00","r":0,"p":[]},{"i":2740,"s":5,"t":"스펀지 팁 달려있는 게 신의 한 수네요.. 손 안 대고 슥슥 펴 바르면 끝나서 아침에 시간 단축 됨. 커버력도 중상 정도? 유분기 많은 지성인데 점심 지나도 잘 안 무너지고 버티네요. 재구매 의사 있음.","u":"네이버 페이 구매자","d":"2026-01-02 22:23:00","r":0,"p":[]},{"i":2739,"s":5,"t":"탐뷰티 처음 써보는데 기대 이상이네요. 따로 브러쉬 안 챙겨도 돼서 여행 갈 때나 수정용으로 챙기기 간편해요. 땀에도 강해서 여름까지 쭉 쓸 수 있을 것 같아요. 추천합니다.","u":"네이버 페이 구매자","d":"2026-01-02 22:15:00","r":0,"p":[]},{"i":2738,"s":5,"t":"쿨톤 21호인데 컬러 자연스럽게 잘 맞아요. 트러블 자국 때문에 스트레스였는데 이거 콕콕 찍어서 스펀지로 펴주면 감쪽같이 사라짐. 지속력도 좋아서 수정 화장 거의 안 해도 돼요.","u":"네이버 페이 구매자","d":"2026-01-02 22:07:00","r":0,"p":[]},{"i":2737,"s":5,"t":"건성인데 눈가 건조해서 컨실러 잘 못 쓰거든요. 근데 이건 얇게 발리면서 마무리는 깔끔해요. 내장 스펀지로 톡톡 두드려주면 주름 끼임 없이 얇게 밀착돼서 다크 커버하기 딱임!","u":"네이버 페이 구매자","d":"2026-01-02 21:44:00","r":0,"p":[]},{"i":2736,"s":5,"t":"파워 지성이라 오후 되면 다 무너지는데 이건 롱웨어라 그런지 유분 올라와도 짱짱하네요. 잡티 커버력도 중상 이상이고 두껍게 안 발려서 답답한 느낌 없어서 좋아요. 정착할 듯.","u":"네이버 페이 구매자","d":"2026-01-02 21:06:00","r":0,"p":[]},{"i":2735,"s":5,"t":"아침 출근 시간에 진짜 꿀템이에요. 스펀지 팁 달려있어서 손에 안 묻히고 슥슥 바르면 블렌딩까지 한 번에 끝나서 너무 편함. 다크서클도 잘 가려지고 밀착력도 좋아서 들뜸 없어요.","u":"네이버 페이 구매자","d":"2026-01-02 21:03:00","r":0,"p":[]},{"i":2734,"s":5,"t":"브러쉬 따로 챙기기 귀찮아서 샀는데 스펀지 팁이 신의 한 수... 톡톡 찍고 펴 바르면 잡티 순삭이라 수정 화장용으로 들고 다니기도 편해요.","u":"네이버 페이 구매자","d":"2026-01-02 20:47:00","r":0,"p":[]},{"i":2733,"s":5,"t":"눈가 주름 끼임 때문에 컨실러 잘 안 쓰는데 이건 스펀지로 얇게 펴 바르니까 안 뜨고 밀착 잘 돼요. 건성인데도 갈라짐 없이 매끈해 보임","u":"네이버 페이 구매자","d":"2026-01-02 19:12:00","r":0,"p":[]},{"i":2732,"s":5,"t":"탐뷰티 신상이라 궁금해서 사봤어요. 이름처럼 가볍게 발리는데 잡티는 싹 가려지네요? 스펀지로 블렌딩하니까 경계 안 지고 자연스러워서 좋아요👍","u":"네이버 페이 구매자","d":"2026-01-02 19:02:00","r":0,"p":[]},{"i":2731,"s":5,"t":"수부지라 오후만 되면 베이스 다 무너지는데 이건 픽싱이 잘 돼서 오래가네요. 땀나도 잘 버텨서 여름까지 쭉 쓸 것 같아요.","u":"네이버 페이 구매자","d":"2026-01-02 18:33:00","r":0,"p":[]},{"i":2730,"s":5,"t":"다크서클이 심해서 샀는데 스펀지 팁이 내장돼있어서 진짜 편해요. 손에 안 묻히고 톡톡 두드리면 끝나서 바쁜 아침에 딱인 듯. 커버력도 기대 이상입니다.","u":"네이버 페이 구매자","d":"2026-01-02 14:18:00","r":0,"p":[]},{"i":2729,"s":5,"t":"광고 보고 반신반의하면서 샀는데 생각보다 요물이네요? 땀 많이 흘리는 체질이라 여름에 쓰기 딱 좋을 거 같아요 밀착력 대박임.. 근데 스펀지 팁이라 세척이 좀 걱정되긴 하는데 커버가 워낙 잘 돼서 안고 갑니다 ㅎ","u":"네이버 페이 구매자","d":"2026-01-02 13:36:00","r":0,"p":[]},{"i":2728,"s":5,"t":"17호 쓰는 쿨톤인데 색상 화사하게 잘 빠졌어요. 보통 커버력 좋으면 두껍게 발리는데 이건 얇게 구름처럼? 올라가서 이름값 하네요 ㅋㅋ 스펀지 팁이라 양 조절도 쉽고 코 옆 붉은기 가리기도 딱 좋아요","u":"네이버 페이 구매자","d":"2026-01-02 13:02:00","r":0,"p":[]},{"i":2727,"s":5,"t":"파우치 부피 줄이려고 샀는데 완전 꿀템.. 스펀지 내장된 게 신의 한 수네요 손 안 대고 블렌딩까지 한 번에 돼서 밖에서 수정 화장할 때 진짜 편해요! 얇게 발리는데 커버는 확실해서 요즘 이것만 손이 가요","u":"네이버 페이 구매자","d":"2026-01-02 12:35:00","r":0,"p":[]},{"i":2726,"s":5,"t":"탐뷰티 처음 써보는데 기대 이상이라 리뷰 남겨요. 일단 커버력이 진짜 좋고 스펀지로 두드리니까 밀착이 잘 돼요. 지성이라 오후 되면 기름 올라와서 다 지워지는데 이건 지속력도 짱짱해요 ㅎ 트러블 자국 싹 가려짐 재구매 의사 있어요","u":"네이버 페이 구매자","d":"2026-01-02 12:24:00","r":0,"p":[]},{"i":2725,"s":5,"t":"스펀지 팁 진짜 편해요ㅠ 따로 브러쉬 안 써도 되고 톡톡 두드리면 끝나서 아침에 시간 단축 짱임. 다크서클이 진짜 심해서 컨실러 유목민이었는데 커버력 미쳤어요.. 건성인데도 눈가 갈라짐 없이 착 붙어서 인생템 등극할 듯","u":"네이버 페이 구매자","d":"2026-01-02 11:52:00","r":0,"p":[]},{"i":2724,"s":5,"t":"광고 보고 반신반의하면서 샀는데 기대 이상이에요. 엄청 얇게 발리는데 웬만한 잡티는 싹 가려줌. 마스크 써도 잘 안 묻어나서 좋네요. 다 쓰면 재구매 의사 있음ㅎ","u":"네이버 페이 구매자","d":"2026-01-02 10:42:00","r":0,"p":[]},{"i":2723,"s":5,"t":"커버력은 진짜 좋은데 내장 스펀지 위생 관리가 좀 신경 쓰이긴 함. 그래도 잡티 하나하나 브러쉬로 가리기 귀찮을 때 그냥 콕 찍어서 문지르면 끝나니까 손이 자주 가요. 색상이 핑베보다는 상아빛이라 붉은기 잡기 좋음.","u":"네이버 페이 구매자","d":"2026-01-02 10:18:00","r":0,"p":[]},{"i":2722,"s":5,"t":"이름처럼 가볍게 올라가는데 커버력은 미쳤음.. 다크서클 심해서 컨실러 유목민이었는데 여기 눕습니다. 스펀지로 톡톡 두드리면 경계 안 지고 자연스러워요. 건조하지 않아서 눈가 주름 부각도 없음.","u":"네이버 페이 구매자","d":"2026-01-02 09:38:00","r":0,"p":[]},{"i":2721,"s":5,"t":"수부지라 오후만 되면 코 옆 다 뜨는데 이건 밀착력이 좋아서 그런지 짱짱하게 버티네요. 땀이랑 유분에 강하다고 해서 여름용으로 샀는데 확실히 지속력 인정. 대신 픽싱이 빨라서 내장 스펀지로 호다닥 펴발라야 함.","u":"네이버 페이 구매자","d":"2026-01-02 07:37:00","r":0,"p":[]},{"i":2720,"s":5,"t":"스펀지 팁이 붙어있어서 따로 브러쉬 안 챙겨도 되는 게 세상 편함. 손에 묻는 거 딱 질색인데 깔끔하게 블렌딩까지 돼요. 다크서클 가리는 용도로 21호 샀는데 주름 끼임 없이 얇게 발리네요. 아침에 퀵메이크업용으로 최고.","u":"네이버 페이 구매자","d":"2026-01-02 06:26:00","r":0,"p":[]},{"i":2719,"s":5,"t":"친구가 추천해서 샀는데 왜 이제 샀나 싶음;; 커버력 미쳤고 지속력도 대박이에요. 아침에 바르고 나가서 수정 화장 한 번도 안 함. 스펀지 일체형이라 휴대하기도 간편해요 재구매 의사 200%","u":"네이버 페이 구매자","d":"2026-01-02 05:23:00","r":0,"p":[]},{"i":2718,"s":5,"t":"건성이라 매트한 거 쓰면 바로 뜨는데 이건 이름처럼 가볍게 올라가요. 스펀지 팁이 생각보다 쫀쫀해서 두드릴수록 밀착 잘 됨. 파데 대신 이것만 얇게 발라도 피부 표현 예쁘게 됨","u":"네이버 페이 구매자","d":"2026-01-02 05:14:00","r":0,"p":[]},{"i":2717,"s":5,"t":"다크서클이 턱 밑까지 내려온 사람인데.. 이거 쓰고 광명 찾았어요ㅠ 주름 끼임 걱정했는데 내장 스펀지로 얇게 깔아주니까 블러 처리한 것처럼 매끈해짐. 여름에 쓰기 딱 좋은 롱웨어 재질이에요!","u":"네이버 페이 구매자","d":"2026-01-02 02:48:00","r":0,"p":[]},{"i":2716,"s":5,"t":"요즘 피부 뒤집어져서 붉은기 많은데 이거 요물이네요. 컨실러 유목민이었는데 탐뷰티로 정착합니다. 스펀지로 펴 바르니까 경계 안 지고 자연스럽게 커버돼요. 밀착력 좋아서 마스크 써도 잘 안 묻어남.","u":"네이버 페이 구매자","d":"2026-01-02 00:18:00","r":0,"p":[]},{"i":2715,"s":5,"t":"스펀지 팁이 달려있어서 따로 브러쉬 안 챙겨도 되는 게 진짜 편해요. 밖에서 수정할 때 손에 안 묻히고 톡톡 두드리면 끝.. 커버력도 좋은데 얇게 발려서 답답한 느낌 없어요. 다크서클 심한 편인데 이거 하나로 해결됨","u":"네이버 페이 구매자","d":"2026-01-01 22:30:00","r":0,"p":[]},{"i":2714,"s":5,"t":"눈 밑이 건조해서 주름 끼임 걱정했는데 얇게 발려서 괜찮네요. 컬러가 너무 노랗지 않아서 21호 쿨톤 피부에도 자연스럽게 어우러져요. 스펀지 팁 위생 관리만 좀 신경 쓰면 될 듯.","u":"네이버 페이 구매자","d":"2026-01-01 18:54:00","r":0,"p":[]},{"i":2713,"s":5,"t":"수정 화장용으로 샀어요. 파우치에 브러쉬 따로 챙기기 귀찮은데 이건 하나만 들고나가면 되니까 간편함. 커버력 좋아서 소량만 써도 충분해요. 세일할 때 사서 가성비 굿.","u":"네이버 페이 구매자","d":"2026-01-01 17:42:00","r":0,"p":[]},{"i":2712,"s":5,"t":"탐뷰티 처음 사보는데 잡티 커버력 미쳤어요... 컨실러 유목민이었는데 여기에 눕습니다. 스펀지로 펴 바르니까 밀착도 잘 되고 두껍게 안 발려서 피부 표현이 예뻐요 👍","u":"네이버 페이 구매자","d":"2026-01-01 16:56:00","r":0,"p":[]},{"i":2711,"s":5,"t":"지성이라 오후만 되면 유분기 폭발하는데 이건 픽싱이 빨라서 오래 버티네요. 땀 나도 잘 안 지워져서 여름까지 잘 쓸 것 같아요. 마무리가 보송해서 기초만 탄탄히 하면 안 뜸.","u":"네이버 페이 구매자","d":"2026-01-01 16:45:00","r":0,"p":[]},{"i":2710,"s":5,"t":"손에 뭐 묻히는 거 딱 질색인데 스펀지 팁 일체형이라 너무 편해요. 콕 찍어서 두드리면 끝이라 바쁜 아침에 최고임. 커버력도 중상이라 짙은 다크서클도 잘 가려집니다.","u":"네이버 페이 구매자","d":"2026-01-01 15:15:00","r":0,"p":[]},{"i":2709,"s":5,"t":"곰손이라 컨실러 쓰면 항상 경계 지는데 이건 팁으로 톡톡하면 블렌딩 끝이라 진짜 편해요. 커버력 높으면 두꺼워지기 마련인데 얇게 밀착돼서 피부 좋아 보인다는 소리 들었음ㅎㅎ","u":"네이버 페이 구매자","d":"2026-01-01 15:00:00","r":0,"p":[]},{"i":2708,"s":5,"t":"그냥 구경하다가 스펀지 달려있는 게 신기해서 사봤는데 의외의 꿀템 발견함.. 따로 브러쉬 안 챙겨도 돼서 수정화장용으로 파우치에 넣고 다녀요. 밀착력도 좋아서 웬만한 잡티는 다 가려짐","u":"네이버 페이 구매자","d":"2026-01-01 14:59:00","r":0,"p":[]},{"i":2707,"s":5,"t":"쿨톤이라 너무 노란끼 도는 건 피하는데 컬러감 딱 예쁘게 빠졌어요. 눈가 주름 끼임 걱정했는데 생각보다 촉촉하게 발리고 마무리는 보송해서 좋아요. 다크서클 가리는 용도로 강추!","u":"네이버 페이 구매자","d":"2026-01-01 12:12:00","r":0,"p":[]},{"i":2706,"s":5,"t":"지성이라 오후만 되면 베이스 다 무너지는 편인데 이건 롱웨어라 그런지 짱짱하게 버티네요. 땀 나도 안 지워져서 이번 여름은 이걸로 정착할 듯. 잡티 커버도 자연스럽게 잘 돼요.","u":"네이버 페이 구매자","d":"2026-01-01 10:59:00","r":0,"p":[]},{"i":2705,"s":5,"t":"탐뷰티 처음 들어봤는데 스펀지 팁 내장된 거 보고 바로 샀어요. 손에 컨실러 묻히기 싫을 때 진짜 딱임.. 커버력도 짱짱해서 다크서클 순삭되네요. 아침에 시간 없을 때 최고예요.","u":"네이버 페이 구매자","d":"2026-01-01 09:22:00","r":0,"p":[]},{"i":2704,"s":5,"t":"반신반의하면서 샀는데 생각보다 물건임;; 땀 많이 흘리는 체질인데 안 지워지고 고정력 대박. 커버력도 상타치. 다 쓰면 또 살 예정","u":"네이버 페이 구매자","d":"2026-01-01 08:49:00","r":0,"p":[]},{"i":2703,"s":5,"t":"건성인데 각질 부각 없이 잘 발림. 보통 봉타입 쓰다가 스펀지 일체형 쓰니까 신세계네여.. 걍 쓱 긋고 두드리면 끝임. 수정 화장용으로 들고 다니기 딱 좋은 사이즈.","u":"네이버 페이 구매자","d":"2026-01-01 05:17:00","r":0,"p":[]},{"i":2702,"s":5,"t":"커버력 ㄱㅊ은듯. 잡티 많은 편이라 샀는데 두껍게 안 발리고 밀착 잘 됨. 근데 스펀지 팁 세척은 좀 귀찮을 수도? 그래도 편해서 매일 손이 감.","u":"네이버 페이 구매자","d":"2026-01-01 01:06:00","r":0,"p":[]},{"i":2701,"s":5,"t":"수부지라 오후 되면 컨실러 다 뜨는데 이건 롱웨어라 그런지 짱짱함. 탐뷰티 첨 들어보는데 베이스 맛집인 듯? 스펀지로 톡톡 두드리면 블렌딩 바로 돼서 화장 시간 줄음ㅋㅋ","u":"네이버 페이 구매자","d":"2025-12-31 22:42:00","r":0,"p":[]},{"i":2700,"s":5,"t":"스펀지팁 달린 거 편해 보여서 샀는데 진짜 개꿀.. 손에 안 묻는 게 젤 큼. 다크서클 심한 편인데 얇게 잘 가려짐. 아침에 바르고 나가도 저녁까지 멀쩡함 ㅇㅇ 재구매 의사 있음.","u":"네이버 페이 구매자","d":"2025-12-31 20:45:00","r":0,"p":[]},{"i":2699,"s":5,"t":"21호 쓰는데 컬러 둥둥 안 뜨고 딱 화사해요. 잿빛 돌면 다크 가릴 때 더 칙칙해 보이는데 이건 맑게 커버됨 ㅋㅋ 스펀지 팁 덕분에 수정 화장할 때도 편해서 파우치 필수템 됐음.","u":"네이버 페이 구매자","d":"2025-12-31 19:42:00","r":0,"p":[]},{"i":2698,"s":5,"t":"똥손이라 컨실러 양 조절 맨날 실패하는데 이건 스펀지 내장이라 그냥 슥 긋고 톡톡하면 끝이라 개편함 ㅠㅠ 밀착 잘돼서 픽싱도 빠르고 묻어남도 거의 없어요. 지속력 인정","u":"네이버 페이 구매자","d":"2025-12-31 17:22:00","r":0,"p":[]},{"i":2697,"s":5,"t":"건성이라 매트한 거 쓰면 눈가 바로 갈라지는데 이건 겉보속촉 느낌? 스펀지로 펴 바르니까 블렌딩 자연스럽게 되고 경계 안 생겨서 조음. 파데 프리 할 때 잡티만 가리고 나가기 굿 🤍","u":"네이버 페이 구매자","d":"2025-12-31 15:29:00","r":0,"p":[]},{"i":2696,"s":5,"t":"트러블 흉터 때문에 커버력 젤 중요하게 보는데 탐뷰티꺼 찐이네요. 얇게 발리는데 커버는 확실함 ㅋㅋ 오후 되면 유분 폭발하는 지성인데 롱웨어라 그런지 안 무너지고 짱짱하게 버텨줌!","u":"네이버 페이 구매자","d":"2025-12-31 15:25:00","r":0,"p":[]},{"i":2695,"s":5,"t":"다크서클 심해서 컨실러 유목민이었는데 이거 물건이네요.. 스펀지 팁 달려있어서 손에 안 묻히고 톡톡 두드리면 싹 가려짐. 주름 끼임도 적고 아침에 퀵메이크업용으로 딱이에요.","u":"네이버 페이 구매자","d":"2025-12-31 15:13:00","r":0,"p":[]},{"i":2694,"s":5,"t":"파우치 부피 줄이는데 일등공신임. 컨실러 브러쉬 따로 안 들고 다녀도 돼서 너무 편해요ㅋㅋㅋ 밖에서 수정화장 할 때 짱임. 코 옆 붉은기랑 잡티 톡톡 찍어주면 깔끔하게 커버됨. 지속력도 짱짱해서 아침에 바르고 나가면 저녁까지 거의 그대로임. 강추!","u":"네이버 페이 구매자","d":"2025-12-31 14:21:00","r":0,"p":[]},{"i":2693,"s":5,"t":"유명하다는 컨실러 다 써봤는데 밀착력은 탐뷰티가 젤 나은 듯?? 들뜨는 거 없이 촥 붙어요 ㄹㅇ.. 스펀지로 톡톡 두드리면 블렌딩도 자연스럽게 잘 됨. 세일할 때 쟁여두려구요ㅎㅎ 고민하시는 분들 걍 사세요 후회 안 함","u":"네이버 페이 구매자","d":"2025-12-31 10:08:00","r":0,"p":[]},{"i":2692,"s":5,"t":"다크서클 커버용으로 샀어요. 이름처럼 가볍게 발리긴 하는데 커버력이 미쳤음.. 얇게 올라가는데 웬만한 건 다 가려지네요. 다만 스펀지 팁 위생이 좀 걱정되긴 함ㅠ 뚜껑 닫을 때 조심해야 하고.. 그래도 편해서 계속 손이 가요. 쿨톤 21호인데 컬러 화사하고 예쁨!","u":"네이버 페이 구매자","d":"2025-12-31 09:47:00","r":0,"p":[]},{"i":2691,"s":5,"t":"지성이라 오후 되면 컨실러 다 녹아서 사라지는데 이건 진짜 오래가네요?? 롱웨어라더니 인정.. 픽싱이 좀 빠른 편이라 바르고 바로 내장 스펀지로 펴줘야 해요. 잡티 커버는 확실히 잘 되는데 건성분들은 기초 탄탄하게 하셔야 할 듯. 저는 유분기 잡아주는 느낌이라 만족합니당👍","u":"네이버 페이 구매자","d":"2025-12-31 09:15:00","r":0,"p":[]},{"i":2690,"s":5,"t":"와 이거 ㄹㅇ 물건임;; 스펀지 팁 달려있어서 걍 슥슥 문지르면 끝이라 넘 편함.. 손에 안 묻는 게 진짜 최고 장점ㅠㅠ 다크서클 가릴 때 브러쉬 찾기 귀찮은데 이건 하나로 퉁칠 수 있어서 좋음! 지속력도 나쁘지 않아요.","u":"네이버 페이 구매자","d":"2025-12-31 07:04:00","r":0,"p":[]},{"i":2689,"s":5,"t":"내돈내산 찐후기임다. 잡티 커버보다는 다크서클이랑 입가 정리용으로 샀는데 얇게 발려서 피부 좋아 보여요. 마스크 써도 거의 안 묻어남..👍 스펀지 달려있는 게 신의 한 수네요 파우치 부피 줄어서 넘 조아요","u":"네이버 페이 구매자","d":"2025-12-31 05:14:00","r":0,"p":[]},{"i":2688,"s":5,"t":"원래 쓰던 팟타입 컨실러가 너무 건조해서 갈아탔는데 발림성 무엇.. 엄청 부드러운데 픽싱되면 딱 고정돼요. 스펀지 팁이라 양 조절도 쉽고 콧볼 옆 붉은기 커버하기 딱 좋음! 지속력도 이 정도면 훌륭합니다","u":"네이버 페이 구매자","d":"2025-12-31 02:43:00","r":0,"p":[]},{"i":2687,"s":5,"t":"탐뷰티 처음 들어봐서 반신반의하며 샀는데 기대 이상이에요! 21호 쿨톤인데 색상 화사하게 잘 빠졌고 트러블 자국 커버 엄청 잘됩니다. 스펀지로 펴 바르니까 경계 안 지고 자연스러워요 곰손분들 무조건 사세요..","u":"네이버 페이 구매자","d":"2025-12-31 02:15:00","r":0,"p":[]},{"i":2686,"s":5,"t":"지성 피부라 오후만 되면 컨실러 다 날아가는데 이건 진짜 짱짱하게 버티네요 ㅋㅋ 땀이랑 유분에 강하다더니 찐인 듯.. 커버력도 좋은데 답답하지 않게 발려서 좋아요. 수정 화장할 때도 퍼프 따로 안 챙겨도 돼서 꿀템 등극입니다","u":"네이버 페이 구매자","d":"2025-12-31 01:27:00","r":0,"p":[]},{"i":2685,"s":5,"t":"아침에 바쁠 때 손에 안 묻히고 슥슥 바르기 너무 편해요. 내장된 스펀지 팁이 생각보다 쫀쫀해서 그냥 톡톡 두드리면 블렌딩 끝남.. 다크서클 가리는 용도로 샀는데 끼임도 없고 얇게 밀착돼서 아주 만족합니다 재구매 의사 100%!","u":"네이버 페이 구매자","d":"2025-12-30 23:08:00","r":0,"p":[]},{"i":2684,"s":5,"t":"광고 보고 반신반의하면서 샀는데 생각보다 퀄리티 좋아서 놀람;; 스펀지가 내용물을 많이 안 먹어서 소량으로도 넓은 부위 커버 가능해요. 마스크 쓰고 운동하고 왔는데도 거의 그대로 남아있음. 다 쓰면 재구매 의사 있어요","u":"네이버 페이 구매자","d":"2025-12-30 22:37:00","r":0,"p":[]},{"i":2683,"s":5,"t":"색상이 진짜 예쁜 상아색이라 다크닝 없이 화사해짐. 스펀지 내장된 게 신의 한 수... 도구 없이도 경계 안 지고 자연스럽게 블러링 돼요. 다만 픽싱이 좀 빠른 편이라 바르고 멍 때리면 안되고 바로 펴발라줘야 안 뭉쳐요 참고하세요!","u":"네이버 페이 구매자","d":"2025-12-30 22:04:00","r":0,"p":[]},{"i":2682,"s":5,"t":"유분 폭발하는 지성인데 이거 롱웨어 인정. 점심시간 지나도 코 옆 끼임이나 무너짐 거의 없어요. 스펀지가 좀 딱딱할까 걱정했는데 생각보다 말랑하고 양 조절 쉬움. 붉은 트러블 자국도 컨실러만으로 90프로는 가려지는 듯? 탐뷰티 처음 써보는데 기대 이상이네요","u":"네이버 페이 구매자","d":"2025-12-30 21:49:00","r":0,"p":[]},{"i":2681,"s":5,"t":"21호 건성 피부입니다. 이름처럼 가볍게 발리는데 밀착력이 미쳤어요. 보통 봉 타입 컨실러는 눈가 주름에 끼임 심한데 이건 얇게 픽싱돼서 주름 부각 없네요. 잡티 커버도 잘되고 무엇보다 수정 화장할 때 브러쉬나 퍼프 따로 안 챙겨도 돼서 넘 편함👍","u":"네이버 페이 구매자","d":"2025-12-30 21:45:00","r":0,"p":[]},{"i":2680,"s":5,"t":"손에 묻히기 싫어서 샀는데 내장 스펀지 팁이 진짜 요물이네요... 걍 쓱 긋고 뒤에 달린 팁으로 톡톡 두드리면 블렌딩 끝이라 아침에 준비 시간 확 줄었어요. 커버력은 기대 안했는데 웬만한 잡티랑 다크서클 푸른기 싹 잡아줘요. 지속력도 좋아서 저녁까지 안 뜸!","u":"네이버 페이 구매자","d":"2025-12-30 19:43:00","r":0,"p":[]},{"i":2679,"s":5,"t":"건성 김미연이라 매트한 컨실러는 피하는 편인데, 이건 겉보속촉 느낌으로 마무리돼요. 스펀지로 톡톡 두드려주면 요철 부각 없이 매끈하게 커버됩니다. 붉은기 커버도 잘 돼서 홍조 있는 분들에게도 잘 맞을 것 같아요.","u":"네이버 페이 구매자","d":"2025-12-30 19:35:00","r":0,"p":[]},{"i":2678,"s":5,"t":"광고 보고 반신반의하면서 샀는데 생각보다 물건이네요? 스펀지가 내장되어 있어서 브러쉬 따로 안 챙겨도 되는 게 신의 한 수.. 커버력은 중상 정도고 두껍게 안 발려서 답답하지 않아요. 여행 갈 때 파우치 짐 줄이기 딱 좋음👍","u":"네이버 페이 구매자","d":"2025-12-30 17:08:00","r":0,"p":[]},{"i":2677,"s":5,"t":"21호 쿨톤인데 컬러가 누렇지 않고 화사하게 예쁘게 뽑혔어요. 눈가 주름이 많은 편이라 뻑뻑한 거 쓰면 끼임 심한데, 내장 스펀지로 펴 바르니까 블렌딩이 자연스럽게 잘 돼요. 다크서클 커버용으로 샀다가 얼굴 전체에 파데 프리로 쓰고 있습니당.","u":"네이버 페이 구매자","d":"2025-12-30 17:00:00","r":0,"p":[]},{"i":2676,"s":5,"t":"수부지 피부라 오후만 되면 유분기 올라와서 컨실러 다 지워지는데, 이건 롱웨어라 그런지 지속력 짱짱해요. 이름처럼 가볍게 올라가는데 밀착력이 좋아서 마스크 써도 잘 안 묻어남.. 탐뷰티 처음 써보는데 기대 이상이라 재구매 의사 있습니다. 잡티 많은 분들 꼭 사세요.","u":"네이버 페이 구매자","d":"2025-12-30 16:17:00","r":0,"p":[]},{"i":2675,"s":5,"t":"스펀지 팁이 달려있어서 손에 안 묻히고 슥슥 바르기 너무 편해요. 다크서클이 심한 편인데 얇게 발리면서도 커버는 확실하게 되네요. 아침에 바쁠 때 이거 하나면 베이스 뚝딱입니다. 수정용으로도 파우치에 넣고 다니기 좋아요.","u":"네이버 페이 구매자","d":"2025-12-30 15:25:00","r":0,"p":[]},{"i":2674,"s":5,"t":"솔직히 스펀지 달린 거 위생 때문에 고민하다 샀는데 편하긴 진짜 편하네요 ㅋㅋ 밖에서 수정화장 할 때 브러쉬 따로 안 챙겨도 돼서 짐이 줄음. 밀착력 좋고 픽싱도 빠른 편이라 펴바를 때 빨리 두드려야 해요. 가성비 굿.","u":"네이버 페이 구매자","d":"2025-12-30 14:44:00","r":0,"p":[]},{"i":2673,"s":5,"t":"다크서클이 심한 편이라 샀는데 두껍게 안 발리고 얇게 올라가서 좋네요. 보통 퍼프로 두드리면 커버된 거 다 벗겨지는데 이건 내장 스펀지로 살살 펴주니까 딱 고정됨. 색상도 칙칙하지 않고 화사해요.","u":"네이버 페이 구매자","d":"2025-12-30 13:14:00","r":0,"p":[]},{"i":2672,"s":5,"t":"탐뷰티 첨 들어보는데 광고 보고 사봤어요. 커버력은 진짜 좋은데 제 피부가 건성이라 그런지 시간 지나면 눈가 주름 끼임이 살짝 있어요. 기초 탄탄하게 하고 바르면 괜찮을 듯. 스펀지는 쫀쫀해서 맘에 듭니다.","u":"네이버 페이 구매자","d":"2025-12-30 12:11:00","r":0,"p":[]},{"i":2671,"s":5,"t":"수부지 피부라 오후만 되면 코 옆이랑 다크서클 쪽 컨실러 다 무너지는데 이건 꽤 오래 버티네요. 땀 흘려도 지저분하게 안 무너져서 좋아요. 스펀지로 톡톡 두드리면 블렌딩도 자연스럽게 잘 됨! 재구매 의사 있습니다 👍","u":"네이버 페이 구매자","d":"2025-12-30 08:42:00","r":0,"p":[]},{"i":2670,"s":5,"t":"스펀지 팁이 달려있어서 손 안 묻히고 슥슥 바르긴 편해요. 근데 뚜껑 닫을 때마다 입구가 좀 지저분해지는 것 같아서 그건 좀 아쉽네요.. 커버력은 다크서클 가리기엔 충분하고 밀착력도 나쁘지 않음. 아침에 급할 때 쓰기엔 딱입니다.","u":"네이버 페이 구매자","d":"2025-12-30 04:33:00","r":0,"p":[]},{"i":2669,"s":5,"t":"스펀지가 달려있어서 위생 걱정은 좀 됐는데 뚜껑 닫기 전에 티슈로 닦아주니 괜찮네요. 일단 손 안 쓰고 커버 가능한 게 제일 큰 장점이고, 픽싱이 빨라서 바르자마자 블렌딩해줘야 해요. 지속력은 진짜 인정.. 헬스장 갔다 왔는데도 거의 그대로 남아있었어요.","u":"네이버 페이 구매자","d":"2025-12-30 04:16:00","r":0,"p":[]},{"i":2668,"s":5,"t":"탐뷰티 처음 써보는데 이름처럼 가볍게 올라가네요. 두껍게 발리는 컨실러 싫어하는데 이건 얇게 밀착되면서도 가릴 건 다 가려줘서 신기해요. 특히 코 옆 붉은기랑 다크서클 커버에 최적화된 느낌? 스펀지가 달려있어서 밖에서 급하게 수정할 때도 거울 보고 슥슥 하면 끝이라 넘 편해요 👍","u":"네이버 페이 구매자","d":"2025-12-30 04:12:00","r":0,"p":[]},{"i":2667,"s":5,"t":"커버력 좋다는 후기 보고 샀는데 잡티 진짜 잘 가려짐. 스펀지 팁이라 양 조절도 쉽고 똥손인데 대충 펴 발라도 경계 안 져서 좋음ㅋㅋ 밀착력도 ㄱㅊ은듯. 근데 너무 많이 바르면 살짝 두꺼워질 수 있으니까 소량만 써도 충분해요. 가성비 굿.","u":"네이버 페이 구매자","d":"2025-12-30 00:14:00","r":0,"p":[]},{"i":2666,"s":5,"t":"지복합성이라 오후만 되면 다크닝 오고 베이스 무너지는 게 일상인데 이건 밀착력이 미쳤어요.. 아침에 바르고 나가서 수정 화장 거의 안 했는데도 저녁까지 짱짱하게 버티네요. 땀이나 유분에도 강하다고 해서 샀는데 확실히 롱웨어 인정입니다. 잡티 가리는 용도로 딱이에요.","u":"네이버 페이 구매자","d":"2025-12-29 22:41:00","r":0,"p":[]},{"i":2665,"s":5,"t":"브러쉬 따로 챙기기 귀찮아서 샀는데 스펀지 팁 내장된 게 진짜 신의 한 수네요. 톡톡 찍어서 바로 블렌딩하면 되니까 손에 묻힐 일도 없고 편해요. 다크서클이 심한 편이라 컨실러 유목민이었는데 얇게 발리면서도 커버력은 확실하네요. 건성이라 눈가 끼임 걱정했는데 생각보다 촉촉하게 마무리돼서 만족합니다. 재구매 의사 있어요.","u":"네이버 페이 구매자","d":"2025-12-29 22:21:00","r":0,"p":[]},{"i":2664,"s":5,"t":"광고 보고 반신반의하며 샀는데 생각보다 퀄리티 좋아서 리뷰 남겨요. 스펀지 일체형이라 파우치 가벼워져서 좋음. 톡 찍고 슥슥 문지르면 끝이라 곰손들도 쓰기 편할 듯. 밀착력 좋아서 파데 대신 이거 하나로 베이스 끝낼 때도 있어요.","u":"네이버 페이 구매자","d":"2025-12-29 22:08:00","r":0,"p":[]},{"i":2663,"s":5,"t":"건성이라 매트할까봐 걱정했는데 이름처럼 구름같이 가볍게 올라가요. 주름 끼임 거의 없고 촉촉하게 발리는데 마무리는 보송해서 신기함.. 잡티 커버용으로 샀는데 다크에도 괜찮네요. 색상은 생각보다 밝게 나온 편이니 참고하세요.","u":"네이버 페이 구매자","d":"2025-12-29 21:20:00","r":0,"p":[]},{"i":2662,"s":5,"t":"지성 피부라 컨실러 쓰면 금방 무너지고 뜨는데 탐뷰티꺼는 픽싱이 빨라서 좋아요. 땀 많이 흘리는 편인데도 거의 그대로 남아있어서 놀랐어요 ㅎ 스펀지 팁 내장된 거 위생적이라 맘에 드는데 팁만 따로 세척이 가능한지는 좀 더 써봐야 알 것 같네요. 여드름 자국 가리기 딱 좋아요.","u":"네이버 페이 구매자","d":"2025-12-29 19:29:00","r":0,"p":[]},{"i":2661,"s":5,"t":"다크서클이 심해서 컨실러 유목민이었는데 이거 물건이네요. 보통 커버력 좋으면 두껍게 발리는데 이건 얇게 밀착되면서 가려질 건 다 가려져요. 스펀지로 블렌딩하니까 경계도 안 생기고 편합니다. 지속력도 짱짱해서 오후까지 수정화장 안 해도 됨.","u":"네이버 페이 구매자","d":"2025-12-29 19:08:00","r":0,"p":[]},{"i":2660,"s":5,"t":"탐뷰티 처음 들어보는데 친구가 추천해서 샀어요. 스펀지 팁이 달려있는게 진짜 신의 한 수네요. 손에 안 묻히고 톡톡 두드리면 끝나서 아침에 화장할 때 시간 단축 대박입니다. 커버력도 중상 이상이고 마스크 써도 잘 안 지워져요. 재구매 의사 있습니다.","u":"네이버 페이 구매자","d":"2025-12-29 18:49:00","r":0,"p":[]},{"i":2659,"s":5,"t":"유명한 백화점 브랜드 컨실러 쓰다가 갈아타봤는데 솔직히 가성비로 따지면 이게 압승인 듯. 내장 스펀지가 생각보다 쫀쫀해서 밀착이 엄청 잘 돼요. 두껍지 않게 잡티만 딱 가려줘서 원래 피부 좋은 척 가능합니다.","u":"네이버 페이 구매자","d":"2025-12-29 18:40:00","r":0,"p":[]},{"i":2658,"s":5,"t":"21호 봄웜인데 컬러 자연스럽게 잘 맞아요! 손에 뭐 묻히기 싫어서 스펀지 달린 거 찾다가 샀는데 기대 이상입니다. 콕콕 찍고 문지르면 3초 컷 가능..ㅋㅋ 커버력도 중상 이상이라 웬만한 붉은기는 다 잡히네요. 재구매 의사 있어요.","u":"네이버 페이 구매자","d":"2025-12-29 18:25:00","r":0,"p":[]},{"i":2657,"s":5,"t":"지성 피부라 오후만 되면 유분 때문에 베이스 다 무너지는데 이건 픽싱력이 대박이네요. 아침에 바르고 저녁까지 다크닝 없이 짱짱하게 유지돼요. 스펀지 팁이라 양 조절도 쉽고 얇게 발려서 답답한 느낌도 없습니다👍","u":"네이버 페이 구매자","d":"2025-12-29 14:23:00","r":0,"p":[]},{"i":2656,"s":5,"t":"다크서클 부자라 컨실러 유목민이었는데 여기에 정착할 듯요. 눈가 주름에 끼임 없이 얇게 밀착되는데 커버력은 미쳤어요ㅋㅋ 두껍게 올라가는 느낌 싫어하시는 분들한테 강추합니다. 스펀지로 블렌딩하니까 경계도 안 지고 자연스러워요.","u":"네이버 페이 구매자","d":"2025-12-29 12:16:00","r":0,"p":[]},{"i":2655,"s":5,"t":"탐뷰티 처음 들어봐서 반신반의했는데 스펀지 팁이 진짜 신의 한 수네요.. 브러쉬 따로 챙기기 귀찮은데 이건 그냥 슥 긋고 내장 스펀지로 톡톡하면 끝이라 너무 편해요. 커버력도 좋아서 웬만한 잡티는 다 가려짐! 지속력도 짱짱해서 수정화장 거의 안 했어요.","u":"네이버 페이 구매자","d":"2025-12-29 11:05:00","r":0,"p":[]},{"i":2654,"s":5,"t":"21호 쿨톤인데 너무 노랗지도 않고 딱 예쁜 상아색이라 맘에 듦. 컨실러랑 도구 따로 챙기기 귀찮았는데 이거 하나면 되니까 파우치 가벼워져서 좋음ㅋㅋ 밀착력 좋아서 위에 쿠션 덧발라도 안 밀려요.","u":"네이버 페이 구매자","d":"2025-12-29 09:47:00","r":0,"p":[]},{"i":2653,"s":5,"t":"탐뷰티 처음 들어보는 브랜드라 반신반의하면서 샀는데 기대 이상이네요? 스펀지가 생각보다 퀄리티 좋아서 자국 안 남고 깔끔하게 발려요. 붉은 기 잡는 데 최고임. 다 쓰면 또 살 듯.","u":"네이버 페이 구매자","d":"2025-12-29 08:22:00","r":0,"p":[]},{"i":2652,"s":5,"t":"다크서클 전용으로 샀는데 컬러감 자연스럽고 좋아요. 제형은 픽싱이 빨라서 바르자마자 블렌딩 해야 함. 스펀지로 팡팡 두드리면 끼임 없이 싹 가려져서 만족ㅎㅎ 건성보단 지성 추천.","u":"네이버 페이 구매자","d":"2025-12-29 06:21:00","r":0,"p":[]},{"i":2651,"s":5,"t":"지복합성이라 오후 되면 코 옆 다 무너지는데 이건 롱웨어라 그런지 짱짱하게 버티네요. 잡티 커버는 확실한데 양 조절 필수임. 콕 찍어서 내장 스펀지로 펴 발라야 얇게 올라가요. 커버력 하나는 인정.","u":"네이버 페이 구매자","d":"2025-12-29 03:50:00","r":0,"p":[]},{"i":2650,"s":5,"t":"스펀지 팁 내장된 게 진짜 신의 한 수... 손에 뭐 묻히는 거 싫어하는데 그냥 슥 긋고 톡톡하면 끝이라 너무 편해요. 다크서클 커버도 잘 되고 밀착력 좋아서 마스크 써도 잘 안 지워짐. 땀 흘려도 그대로라 여름에 쓰기 좋을 듯.","u":"네이버 페이 구매자","d":"2025-12-29 02:40:00","r":0,"p":[]},{"i":2649,"s":5,"t":"브러쉬 세척하기 귀찮은 게으름뱅이들에게 강추 ㅋㅋ 뚜껑 열고 톡톡하고 뒤에 달린 스펀지로 펴 바르면 끝이라 화장 시간 5분 단축됨. 커버력은 중상 정도? 아주 진한 점은 완벽하겐 안 가려지는데 자잘한 잡티나 다크는 싹 가려짐. 파우치 부피 줄어서 좋음.","u":"네이버 페이 구매자","d":"2025-12-29 01:26:00","r":0,"p":[]},{"i":2648,"s":5,"t":"21호 봄웜입니다. 파데 답답해서 파데프리용으로 쓰려고 샀어요. 스펀지 팁이 생각보다 쫀쫀해서 모공 커버도 잘 됨. 너무 매트하지 않고 적당히 보송하게 마무리돼서 요즘같이 더운 날씨에 쓰기 딱 좋음. 무너짐이 더럽지 않아서 수정 화장용으로도 합격드립니다👍","u":"네이버 페이 구매자","d":"2025-12-29 01:15:00","r":0,"p":[]},{"i":2647,"s":5,"t":"광고가 너무 많이 떠서 속는 셈 치고 사봤는데 기대 이상입니다. 여드름 흉터랑 붉은기 많은 23호 피부인데, 컨실러 브러쉬 따로 안 쓰고 내장 스펀지로만 웬만한 잡티는 다 가려져요. 지속력도 짱짱해서 마스크 써도 잘 안 묻어남. 다만 양 조절은 필수임. 아주 소량만 콕 찍어서 블렌딩하면 깐달걀 가능함.","u":"네이버 페이 구매자","d":"2025-12-29 01:13:00","r":0,"p":[]},{"i":2646,"s":5,"t":"아니 이거 외않사요? 다크서클 때문에 컨실러 유목민 생활 5년 차인데 드디어 정착함. 제형이 이름처럼 구름같이 가벼운데 밀착력 미쳤음.. 아침에 바르고 헬스장 다녀왔는데 땀 흘려도 거의 그대로 유지됨 ㄷㄷ 스펀지로 두드리면 경계지지도 않고 자연스러움. 세일할 때 쟁여두세요.","u":"네이버 페이 구매자","d":"2025-12-28 23:24:00","r":0,"p":[]},{"i":2645,"s":5,"t":"나스 팟컨실러 쓰다가 이걸로 갈아타봤는데 대만족임. 탐뷰티? 처음 들어보는 브랜드라 고민했는데 스펀지 팁 달려있는 게 신의 한 수.. 밖에서 수정화장 할 때 손에 컨실러 묻히기 싫잖아요 ㅠ 이건 그냥 톡 찍고 슥슥 문지르면 끝이라 너무 편함. 다크서클 커버할 때 얇게 올라가는데 커버력은 확실해서 눈가 주름 끼임도 적은 편. 건성인데도 갈라짐 없이 잘 붙어있네요.","u":"네이버 페이 구매자","d":"2025-12-28 23:11:00","r":0,"p":[]},{"i":2644,"s":5,"t":"복합성 피부입니다. 스펀지 어플리케이터가 진짜 물건이네요. 양 조절도 쉽고 손가락으로 바르는 것보다 훨씬 얇고 고르게 발려요. 땀 흘려도 지저분하게 안 무너지고 딱 고정되어 있어요. 탐뷰티 베이스 맛집이네요.","u":"네이버 페이 구매자","d":"2025-12-28 21:17:00","r":0,"p":[]},{"i":2643,"s":5,"t":"다크서클 때문에 컨실러 유목민 생활 청산합니다.. 보통 커버력 좋으면 두껍고 텁텁한데 이건 이름처럼 가볍게 올라가면서 잡티는 싹 가려줘요. 코 옆 붉은기 커버할 때도 스펀지 팁으로 꾹꾹 누르니까 밀착 대박이에요. 👍 친구 추천으로 샀는데 대만족!","u":"네이버 페이 구매자","d":"2025-12-28 21:00:00","r":0,"p":[]},{"i":2642,"s":5,"t":"지성 피부라 오후만 되면 화장 다 녹아내리는데 이건 롱웨어라 그런지 지속력 인정합니다. 수정 화장할 때도 쿠션 안 쓰고 이걸로 뭉친 부분만 톡톡 정리해주면 깔끔해요. 스펀지가 내장되어 있어서 브러쉬 따로 안 챙겨도 되는 게 제일 큰 장점인 듯.. 여행 갈 때 필수템 될 것 같아요.","u":"네이버 페이 구매자","d":"2025-12-28 20:58:00","r":0,"p":[]},{"i":2641,"s":5,"t":"21호 쿨톤인데 컬러가 칙칙하지 않고 예쁘게 나왔어요. 여드름 흉터 가리는 용도로 샀는데 커버력 진짜 좋구요. 스펀지로 펴 바르니까 경계 안 지고 자연스럽게 블렌딩 돼서 곰손인 저한테 딱이에요. 오후 돼도 유분에 안 무너지고 짱짱하게 버티네요. 재구매 의사 100%입니다.","u":"네이버 페이 구매자","d":"2025-12-28 20:34:00","r":0,"p":[]},{"i":2640,"s":5,"t":"탐뷰티 처음 들어보는데 후기 좋아서 사봤어요. 일단 스펀지 팁이 달려있어서 손에 안 묻히고 톡톡 두드리면 끝이라 세상 편해요..ㅋㅋ 다크서클 심한 편인데 주름 끼임 없이 커버 잘 되네요. 건성인데도 갈라짐 없이 쫀쫀하게 밀착됩니다. 아침에 바쁠 때 쓱쓱 긋고 두드리면 돼서 요즘 이것만 써요.","u":"네이버 페이 구매자","d":"2025-12-28 17:54:00","r":0,"p":[]},{"i":2639,"s":5,"t":"이름값 하네요 진짜 구름처럼 가볍게 발림ㅋㅋ 스펀지로 펴 바르니까 블렌딩도 쉽고 곰손도 금방 적응 가능해요!","u":"네이버 페이 구매자","d":"2025-12-28 17:29:00","r":0,"p":[]},{"i":2638,"s":5,"t":"잡티가 많은 편이라 컨실러 유목민이었는데 여기에 눕습니다.. 두껍게 안 올라가고 가볍게 커버돼서 피부 좋아 보여요 지속력도 짱짱함👍","u":"네이버 페이 구매자","d":"2025-12-28 16:32:00","r":0,"p":[]},{"i":2637,"s":5,"t":"SNS에서 난리길래 속는 셈 치고 사봤는데 진짜 얇게 발리네요?? 눈가 주름 끼임도 거의 없고 무엇보다 다크서클 커버가 미쳤음.. 다 쓰면 또 살 거예요","u":"네이버 페이 구매자","d":"2025-12-28 15:49:00","r":0,"p":[]},{"i":2636,"s":5,"t":"수부지라 오후만 되면 코 옆 다 끼는데 이건 밀착력 대박이네요 픽싱도 빠르고 땀 흘려도 잘 안 무너져요 여름에 쓰기 딱 좋을 듯","u":"네이버 페이 구매자","d":"2025-12-28 14:36:00","r":0,"p":[]},{"i":2635,"s":5,"t":"스펀지 팁 달려있는 거 진짜 신의 한 수.. 바쁜 아침에 톡톡 두드리면 끝이라 너무 편해요 커버력도 기대 이상이고 다크서클 순삭됨;; 저처럼 귀차니즘 심한 분들한테 강추","u":"네이버 페이 구매자","d":"2025-12-28 11:39:00","r":0,"p":[]},{"i":2634,"s":5,"t":"여행 갈 때 브러쉬 챙기기 귀찮아서 샀는데 개꿀템.. 잡티 커버부터 블렌딩까지 이거 하나로 다 되니까 파우치 가벼워져서 넘 좋아요 ㅠ 지속력도 꽤 길어서 수정 화장 딱히 안 해도 됨. 21호 쿨톤인데 컬러 자연스럽게 잘 뽑힌 듯!","u":"네이버 페이 구매자","d":"2025-12-28 10:16:00","r":0,"p":[]},{"i":2633,"s":5,"t":"커버력은 진짜 좋은데 양 조절이 관건이에요. 팁으로 아주 소량만 콕 찍고 뒤에 달린 스펀지로 살살 펴주면 블렌딩은 자연스럽게 잘 됨. 붉은기 커버는 완벽한데 극건성인 저한테는 눈가가 나중에 살짝 건조해서 기초 탄탄하게 하고 발라야 할 듯해요.","u":"네이버 페이 구매자","d":"2025-12-28 09:58:00","r":0,"p":[]},{"i":2632,"s":5,"t":"탐뷰티 신상이라 궁금해서 내돈내산 해봤는데 생각보다 물건이네요. 트러블 자국 많은데 컨실러 브러쉬 따로 안 쓰고 내장 스펀지로만 가려도 충분해요. 픽싱이 좀 빠른 편이라 바르고 바로 펴발라줘야 경계 안 생깁니다!!","u":"네이버 페이 구매자","d":"2025-12-28 08:50:00","r":0,"p":[]},{"i":2631,"s":5,"t":"수부지라 오후만 되면 베이스 다 무너지는데 이건 롱웨어라 그런지 짱짱하게 버티네요? 땀이랑 유분에 강하다고 해서 샀는데 마스크 썼다 벗어도 거의 안 벗겨짐 ㅎ 커버력은 좋은데 두껍게 발리는 느낌 없어서 답답하지 않아요.","u":"네이버 페이 구매자","d":"2025-12-28 05:59:00","r":0,"p":[]},{"i":2630,"s":5,"t":"스펀지 팁 내장된 게 진짜 신의 한 수네요.. 바쁜 아침에 브러쉬 찾을 필요 없이 톡톡 두드리면 끝나서 너무 편해요. 다크서클 심한 편인데 커버력도 상타치고 무엇보다 얇게 밀착돼서 눈가 주름 끼임이 덜해서 만족합니다. 다 쓰면 재구매 의사 있어요.","u":"네이버 페이 구매자","d":"2025-12-28 05:26:00","r":0,"p":[]},{"i":2629,"s":5,"t":"SNS에서 광고하길래 속는 셈 치고 사봤는데 생각보다 너무 좋아서 당황;; 턱 쪽에 트러블 흉터가 많은데 소량으로도 완벽하게 가려져요. 스펀지로 경계 풀어주면 티 안 나고 자연스럽게 내 피부처럼 표현됩니다. 다 쓰면 또 살 것 같아요.","u":"네이버 페이 구매자","d":"2025-12-28 04:39:00","r":0,"p":[]},{"i":2628,"s":5,"t":"21호 쿨톤인데 1호 사용하니까 하이라이팅 효과도 있고 딱 예쁘게 밝혀주네요. 내장 스펀지가 너무 말랑하지 않고 적당히 힘 있어서 두드릴수록 밀착이 잘 돼요. 외출해서 수정할 때 쿠션 대신 이거 하나만 들고나가도 돼서 파우치가 가벼워졌어요~","u":"네이버 페이 구매자","d":"2025-12-28 04:11:00","r":0,"p":[]},{"i":2627,"s":5,"t":"수부지 피부라 오후만 되면 유분 때문에 베이스가 다 무너지는데, 이 컨실러는 픽싱력이 진짜 좋아서 저녁까지 멀쩡해요. 잡티 위에 콕 찍어두고 살짝 말린 뒤에 스펀지로 펴 바르면 커버력 최상입니다 ㅋㅋㅋ 탐뷰티 처음 써보는데 베이스 맛집인 듯.","u":"네이버 페이 구매자","d":"2025-12-28 03:32:00","r":0,"p":[]},{"i":2626,"s":5,"t":"다크서클이 심한 편이라 컨실러 유목민이었는데 이거 물건이네요.. 보통 커버력 좋으면 두껍게 발려서 눈가 주름에 끼는데, 이건 얇게 밀착되면서 커버는 확실하게 돼요. 이름처럼 가볍게 올라가서 답답한 느낌도 없고 하루 종일 다크닝 없이 유지되네요 재구매 의사 있습니다!","u":"네이버 페이 구매자","d":"2025-12-28 02:53:00","r":0,"p":[]},{"i":2625,"s":5,"t":"스펀지 팁이 내장되어 있어서 따로 브러쉬나 퍼프 안 꺼내도 되는 게 진짜 편해요. 손에 묻는 거 질색인데 톡톡 찍고 뒤에 달린 스펀지로 블렌딩하면 끝이라 수정 화장용으로도 딱입니다. 커버력은 중상 정도 되고 픽싱이 빨라서 다크서클 커버하고 바로 파데 올려도 안 밀려요.","u":"네이버 페이 구매자","d":"2025-12-28 01:43:00","r":0,"p":[]},{"i":2624,"s":5,"t":"내돈내산 솔직 리뷰.\n광고가 너무 떠서 반신반의하며 샀는데 생각보다 좋아서 놀람 ㅋㅋ 일단 스틱형이라 휴대하기 편하고, 팁이 쫀쫀해서 피부에 촥 붙음.\n커버력은 중상 정도? 아주 진한 점은 안 가려지는데 붉은기나 다크는 완벽 커버 가능. 무엇보다 두껍게 안 발려서 피부가 편안함. 더 클라우드 이름값 하네요 ㅎ 여름에 쓰기 딱 좋은 질감입니다.","u":"네이버 페이 구매자","d":"2025-12-28 01:37:00","r":0,"p":[]},{"i":2623,"s":5,"t":"아니 이거 왜 안 유명함..? 😳 친구가 추천해서 써봤는데 진짜 물건임. 똥손이라 컨실러 쓰면 항상 경계 지고 티 났는데 이건 내장 스펀지로 문지르니까 경계 1도 안 지고 자연스러움.\n잡티 커버도 잘 되는데 저는 수정 화장용으로 더 잘 쓰는 중이에요. 마스크 닿는 부분 벗겨졌을 때 톡톡 해주면 감쪽같음. 건성인데 기초만 탄탄히 하면 크게 건조함 못 느꼈어요.","u":"네이버 페이 구매자","d":"2025-12-27 23:27:00","r":0,"p":[]},{"i":2622,"s":5,"t":"평소에 헤ra 21호 씁니다. 컬러는 너무 노랗지도 붉지도 않은 딱 예쁜 상아색이라 맘에 들어요. 다크서클 커버하려고 샀는데 눈가 주름 끼임도 적고 얇게 밀착됨.\n근데 스펀지 팁 위생 관리는 좀 신경 써야 할 거 같아요. 빨아 쓸 수가 없으니 티슈로 잘 닦아줘야 함.. 그거 빼곤 제품력은 나무랄 데가 없네요. 올영 세일할 때 쟁여두세요.","u":"네이버 페이 구매자","d":"2025-12-27 22:57:00","r":0,"p":[]},{"i":2621,"s":5,"t":"지성 피부라 오후만 되면 베이스 다 무너지는 사람입니다 ㅠ 롱웨어라길래 속는 셈 치고 샀는데 밀착력 진짜 좋네요. 픽싱이 엄청 빨라요. 바르자마자 내장 팁으로 빠르게 펴 발라야 함.\n장점: 커버력 상, 지속력 최상, 스펀지 편함\n단점: 건성한텐 좀 건조할 수 있음\n여드름 자국 많은 볼 쪽에 콕콕 찍고 두드려주면 파데 없이도 외출 가능해요 ㅋㅋ 땀 많이 흘리는 분들 강추.","u":"네이버 페이 구매자","d":"2025-12-27 22:54:00","r":0,"p":[]},{"i":2620,"s":5,"t":"컨실러 유목민인데 정착할 듯요. 보통 팟타입은 먼지 묻고 리퀴드는 커버력이 아쉬운데 이건 딱 그 중간 장점만 합친 느낌? 스펀지 팁이 달려있어서 손에 안 묻히고 톡톡 두드리면 블렌딩 끝이라 세상 편해요.\n다크서클이 푸른 편이라 웬만한 걸로 안 가려지는데 이건 얇게 두 번 올리니까 싹 가려짐..ㄷㄷ 지속력도 좋아서 아침에 바르고 저녁에 거울 봐도 다크닝 거의 없어요. 탐뷰티 처음 들어보는데 베이스 맛집이네요. 재구매 의사 200% 있음.","u":"네이버 페이 구매자","d":"2025-12-27 21:45:00","r":0,"p":[]},{"i":2619,"s":5,"t":"수정 화장용으로 샀는데 브러쉬 따로 안 챙겨도 돼서 편해요. 커버력도 좋고 지속력도 쏘쏘. 다 쓰면 또 살 것 같아요.","u":"네이버 페이 구매자","d":"2025-12-27 19:39:00","r":0,"p":[]},{"i":2618,"s":5,"t":"SNS 보고 샀는데 기대 이상이에요. 밀착력이 좋아서 들뜸 없이 피부에 착 붙는 느낌? 파데 안 쓰고 이걸로 잡티만 가리고 나가도 될 정도로 커버력 짱짱합니다.","u":"네이버 페이 구매자","d":"2025-12-27 17:45:00","r":0,"p":[]},{"i":2617,"s":5,"t":"지성 피부라 오후 되면 베이스 무너지는데 이건 픽싱되면 땀나도 잘 버티네요. 잡티 커버는 진짜 확실한데 스펀지 팁 위생 관리가 좀 신경 쓰이긴 해요. 그래도 제품 자체는 만족!","u":"네이버 페이 구매자","d":"2025-12-27 17:24:00","r":0,"p":[]},{"i":2616,"s":5,"t":"건성이라 눈가 주름 끼임 걱정했는데 생각보다 촉촉하게 발리네요. 스펀지로 톡톡 두드리면 다크서클 순삭입니다.. 커버력 좋은데 얇게 발려서 답답한 느낌 없어서 좋아요.","u":"네이버 페이 구매자","d":"2025-12-27 14:36:00","r":0,"p":[]},{"i":2615,"s":5,"t":"[수부지 / 21호] 스펀지 팁이 내장되어 있어서 손에 안 묻히고 쓱쓱 바르기 진짜 편해요. 커버력도 중상 정도? 다크서클 가리기에 딱이고 지속력도 나쁘지 않네요. 다만 양 조절 잘못하면 살짝 두꺼워질 수 있으니 주의.","u":"네이버 페이 구매자","d":"2025-12-27 13:37:00","r":0,"p":[]},{"i":2614,"s":5,"t":"SNS에서 핫하길래 사봤는데 기대 이상임. 손에 뭐 묻는 거 싫어하는 사람들한테 강추,, 커버력은 짱짱한데 마무리는 뽀송해서 여름에 쓰기 딱 좋을 듯 재구매 의사 있음!","u":"네이버 페이 구매자","d":"2025-12-27 13:33:00","r":0,"p":[]},{"i":2613,"s":5,"t":"다크서클 부자라 컨실러 유목민이었는데 여기에 정착함. 팁이 내장돼있어서 양 조절 쉬운 게 신의 한 수,, 두껍지 않게 올라가서 답답한 느낌 1도 없음. 쿨톤인데 컬러도 딱 맞아요","u":"네이버 페이 구매자","d":"2025-12-27 13:01:00","r":0,"p":[]},{"i":2612,"s":5,"t":"가지고 있는 컨실러 중에 밀착력 젤 좋은 듯. 이름처럼 가볍게 올라가는데 커버는 확실해서 신기함.. 건성인데 눈가 주름 끼임도 거의 없고 스펀지로 펴바르니까 자국도 안 남아서 굿굿","u":"네이버 페이 구매자","d":"2025-12-27 12:30:00","r":0,"p":[]},{"i":2611,"s":5,"t":"파워 지성이라 컨실러 금방 지워지는데 이건 찐으로 오래감. 땀 엄청 흘렸는데도 안 무너지고 그대로라 놀랐음;; 잡티 커버는 말할 것도 없고 블렌딩이 진짜 자연스럽게 잘 됨","u":"네이버 페이 구매자","d":"2025-12-27 12:00:00","r":0,"p":[]},{"i":2610,"s":5,"t":"와 이거 물건이네요,, 스펀지 팁이 달려있어서 따로 브러쉬 안 꺼내도 되는 게 진짜 편함ㅠ 걍 슥 긋고 톡톡 두드리면 다크서클 순삭임다. 밀착력도 좋아서 수정화장 거의 안 했어요","u":"네이버 페이 구매자","d":"2025-12-27 11:53:00","r":0,"p":[]},{"i":2609,"s":5,"t":"일단 파우치에 쏙 들어가는 사이즈라 수정 화장용으로 딱이에요. 스펀지 팁이 달려있어서 밖에서도 손 안 대고 톡톡 수정 가능해서 위생적입니다. 잡티 커버력은 중상 정도 되고 지속력도 꽤 길어요. 세일할 때 배송비 맞추려고 샀는데 의외의 꿀템 발견함 ㅋㅋ","u":"네이버 페이 구매자","d":"2025-12-27 10:07:00","r":0,"p":[]},{"i":2608,"s":5,"t":"건성 김미연이라 매트할까봐 걱정했는데 각질 부각 없이 촥 붙어요. 이름처럼 구름같이 가볍게 올라가는 느낌? 다크서클이랑 코 옆 붉은기 커버용으로 쓰고 있는데 눈가 주름 끼임 별로 없어서 좋았습니다. 양 조절도 쉬워서 화장 초보 분들이 쓰기 좋을 것 같아요!","u":"네이버 페이 구매자","d":"2025-12-27 08:11:00","r":0,"p":[]},{"i":2607,"s":5,"t":"탐뷰티 베이스 맛집이라던데 컨실러도 잘하네요. 제형은 너무 묽지도 꾸덕하지도 않아서 딱 좋았어요. 무엇보다 땀이랑 유분에 강하다고 해서 샀는데 운동하고 나서도 거의 그대로라 놀랐습니다.. 마스크 묻어남도 적고 여름용 컨실러로 정착하려구요.","u":"네이버 페이 구매자","d":"2025-12-27 07:09:00","r":0,"p":[]},{"i":2606,"s":5,"t":"커버부터 블렌딩까지 한 번에 된다길래 반신반의하면서 구매했어요. 근데 진짜 요물이네요.. 스펀지가 생각보다 탄탄해서 결 자국 없이 깔끔하게 발려요. 잡티 많은 23호인데 파데 안 쓰고 이 컨실러로만 베이스 깔아도 피부 표현 예쁘게 됨. 대신 스펀지 팁 세척은 좀 신경 써야 할 듯? 그래도 휴대성 좋아서 만족합니다.","u":"네이버 페이 구매자","d":"2025-12-27 05:41:00","r":0,"p":[]},{"i":2605,"s":5,"t":"손에 뭐 묻히기 싫어서 스펀지 팁 달린 거 찾다가 샀는데 진짜 편해요! ㅋㅋㅋ 그냥 슥 긋고 내장된 팁으로 톡톡 두드리면 끝이라 바쁜 아침에 최고입니다. 다크서클이 짙은 편이라 커버력 중요하게 보는데 얇게 발리면서도 가릴 건 다 가려주네요. 오후 되면 유분 올라와서 무너질 줄 알았는데 밀착력이 좋아서 그런지 짱짱하게 버텼어요.","u":"네이버 페이 구매자","d":"2025-12-27 04:17:00","r":0,"p":[]},{"i":2604,"s":5,"t":"친구 추천으로 샀는데 요새 이것만 써요. 두껍게 안 발리는데 붉은기 다 가려줌.. 스펀지 팁이라 수정 화장할 때도 들고 다니면서 톡톡 하기 좋음. 다 쓰면 또 살 예정.","u":"네이버 페이 구매자","d":"2025-12-27 03:40:00","r":0,"p":[]},{"i":2603,"s":5,"t":"탐뷰티 런칭하자마자 사보고 좋아서 쟁여둠. 스펀지가 내용물 적당히 뱉어내서 양 조절 쉽고 무엇보다 밀착력이 대박이에요. 트러블 자국 많은데 컨실러 브러쉬 따로 안 써도 돼서 삶의 질 올라감 :)","u":"네이버 페이 구매자","d":"2025-12-27 01:09:00","r":0,"p":[]},{"i":2602,"s":5,"t":"이름처럼 가볍게 발리는데 커버력은 확실해서 신기해요. 눈가 주름 끼임 걱정했는데 얇게 발려서 그런지 깔끔하게 유지됨. 스펀지로 펴 바르니까 블렌딩 따로 필요 없어서 곰손한테 강추.","u":"네이버 페이 구매자","d":"2025-12-26 22:20:00","r":0,"p":[]},{"i":2601,"s":5,"t":"파워 지성이라 오후만 되면 베이스 다 무너지는데 이건 밀착력이 진짜 좋네요. 픽싱 빨리 돼서 땀 나도 안 지워짐.. 여름에도 잘 쓸 듯! 커버력은 말해 뭐해 잡티 순삭임.","u":"네이버 페이 구매자","d":"2025-12-26 22:13:00","r":0,"p":[]},{"i":2600,"s":5,"t":"스펀지 팁 내장된 거 진짜 신의 한 수;; 바쁜 아침에 톡톡 두드리면 끝이라 손에 안 묻어서 너무 편해요. 다크서클 심한 편인데 이거 하나로 커버 쌉가능. 지속력도 짱짱해서 수정 화장 거의 안 함.","u":"네이버 페이 구매자","d":"2025-12-26 20:12:00","r":0,"p":[]},{"i":2599,"s":5,"t":"베이스 유목민이었는데 여기에 정착합니다. 색상이 진짜 깔끔하게 뽑혔고 무엇보다 픽싱이 빨라서 좋아요. 스펀지로 톡톡 두드리면 샵에서 받은 것처럼 피부 표현 예쁘게 돼요.","u":"네이버 페이 구매자","d":"2025-12-26 18:33:00","r":0,"p":[]},{"i":2598,"s":5,"t":"건성 김미연인데 각질 부각 없이 매끈하게 올라가요. 이름처럼 가볍게 발리는데 커버력은 확실하네요. 블렌딩도 자연스럽게 잘 돼서 경계 안 지고 초보자분들이 쓰기 좋을 거 같아요 👍","u":"네이버 페이 구매자","d":"2025-12-26 16:33:00","r":0,"p":[]},{"i":2597,"s":5,"t":"잡티 가릴 때 브러쉬 따로 챙기기 귀찮은데 이건 스펀지 내장이라 하나만 들고 다니면 돼서 너무 좋아요. 커버력도 상급이라 콕콕 찍어서 두드리면 끝납니다. 여행 갈 때 파우치 짐 줄이기 딱이에요.","u":"네이버 페이 구매자","d":"2025-12-26 15:27:00","r":0,"p":[]},{"i":2596,"s":5,"t":"파워 지성이라 오후만 되면 베이스 다 무너지는데 이건 진짜 짱짱하게 버티네요. 땀 많이 흘린 날에도 수정 화장 거의 안 했어요. 밀착력 대박입니다.. 지속력 중요하게 생각하시는 분들 강추요.","u":"네이버 페이 구매자","d":"2025-12-26 12:55:00","r":0,"p":[]},{"i":2595,"s":5,"t":"스펀지 팁이 달려있어서 손에 안 묻히고 슥슥 바르기 너무 편해요. 다크서클이 심한 편이라 컨실러 필수인데 주름 끼임 없이 커버 잘 되네요. 아침에 바르고 나가도 저녁까지 다크닝 없이 멀쩡합니다. 재구매 의사 있어요!","u":"네이버 페이 구매자","d":"2025-12-26 10:22:00","r":0,"p":[]},{"i":2594,"s":5,"t":"[쿨톤/밝은21호] 베이스 두껍게 하는 거 싫어해서 컨실러 잘 안 쓰는데 이건 얇게 발려서 좋네요. 팁으로 콕콕 찍고 내장 스펀지로 펴주면 경계 1도 없이 내 피부처럼 됨. 잡티보다는 다크서클이랑 톤 보정용으로 샀는데 아주 만족합니당. 땀에도 강해서 운동 갈 때 발라도 안 지워져요 굳굳","u":"네이버 페이 구매자","d":"2025-12-26 10:13:00","r":0,"p":[]},{"i":2593,"s":5,"t":"파워 지성이라 오후만 되면 베이스 무너지는 사람인데 이거 지속력 미쳤어요.. 아침에 바르고 나가서 저녁에 들어왔는데 다크서클이랑 코 옆 붉은기 그대로 커버되어 있음;; 스펀지 팁은 위생상 좀 걱정됐는데 닦아쓰기 편해서 괜찮은 듯요. 커버력 좋은데 답답한 느낌 없어서 요즘 데일리로 쓰는 중.","u":"네이버 페이 구매자","d":"2025-12-26 08:54:00","r":0,"p":[]},{"i":2592,"s":5,"t":"탐뷰티 처음 들어보는 브랜드라 고민했는데 후기 좋아서 사봄. 스펀지 팁이 달려있어서 쿠션 바르기 전에 슥 긋고 두드리면 끝이라 화장 시간 확 줄어듬ㅎㅎ 밀착력이 좋아서 그런지 하루 종일 들뜸 없이 잘 붙어있네요. 다크닝도 거의 없어서 수정 화장용으로 들고 다니기 딱 좋아요.","u":"네이버 페이 구매자","d":"2025-12-26 07:18:00","r":0,"p":[]},{"i":2591,"s":5,"t":"[수부지/21호] 컨실러 유목민이라 신상 떴길래 바로 질러봄. 제형이 너무 뻑뻑하지 않아서 눈가에 발라도 주름 끼임 없어서 좋아요. 스펀지로 톡톡 두드리면 경계 안 지고 자연스럽게 블렌딩되는데 커버력 무엇..? 붉은 트러블 자국도 한 번에 가려지네요. 지속력 테스트 해봤는데 마스크 쓰고 땀 흘려도 거의 그대로라 여름에 쓰기 딱일 듯.","u":"네이버 페이 구매자","d":"2025-12-26 05:05:00","r":0,"p":[]},{"i":2590,"s":5,"t":"인스타 광고 보고 반신반의하며 샀는데 생각보다 꿀템.. 스펀지 팁 내장된 게 신의 한 수네요. 브러쉬 따로 안 챙겨도 돼서 수정 화장할 때 진짜 편해요. 다크서클 심한 편이라 커버력 중요하게 보는데 얇게 발리면서도 가려질 건 다 가려짐! 다만 처음 쓸 때 양 조절 조심해야 할 듯.. 픽싱이 빨라서 바르고 바로 펴 발라야 예쁘게 표현돼요.","u":"네이버 페이 구매자","d":"2025-12-26 03:23:00","r":0,"p":[]},{"i":2589,"s":5,"t":"이름이 왜 클라우드인지 알 것 같아요. 제형이 진짜 가볍고 부드럽게 발리는데 커버는 다 됨.. 보통 커버력 높으면 텁텁한데 이건 얇게 착 붙는 느낌? 스펀지 팁이 말랑해서 자극도 없고 블렌딩도 쉬워서 곰손들도 쓰기 편할 것 같아요. 세일할 때 쟁여야겠음 ㅋㅋ","u":"네이버 페이 구매자","d":"2025-12-25 23:55:00","r":0,"p":[]},{"i":2588,"s":5,"t":"수정용으로 들고 다니려고 샀는데 손에 안 묻히고 스펀지로 톡톡하면 되니까 너무 편해요. 밀착력이 좋아서 그런지 마스크 꼈다 벗어도 거의 안 묻어나있음.. 코 옆 붉은기 가리기 딱 좋고 무엇보다 휴대성이 갑이라 파우치 필수템 됐어요👍 재구매 의사 있습니당","u":"네이버 페이 구매자","d":"2025-12-25 21:35:00","r":0,"p":[]},{"i":2587,"s":5,"t":"여드름 흉터 때문에 커버력 중요하게 생각하는데 탐뷰티가 찐이네요. 컨실러 잘못 쓰면 두꺼워지는데 이건 얇은데도 붉은기 싹 가려줘요. 내장 스펀지로 경계 풀어주니까 컨실러 바른 티도 안 나고 자연스러움 ㅋㅋ 21호 쿨톤인데 1호 컬러 화사하게 잘 맞아요.","u":"네이버 페이 구매자","d":"2025-12-25 20:39:00","r":0,"p":[]},{"i":2586,"s":5,"t":"수부지라 오후만 되면 티존 다 무너지는데 이건 롱웨어라 그런지 진짜 짱짱하게 버티네요. 유분 올라와도 더럽게 무너지는 게 아니라서 수정 화장 거의 안 해도 됨.. 픽싱이 빨라서 바르고 바로 스펀지로 펴바르는 게 좋아요! 여름에도 쓰기 좋을 듯.","u":"네이버 페이 구매자","d":"2025-12-25 20:09:00","r":0,"p":[]},{"i":2585,"s":5,"t":"스펀지 팁 달려있는 게 진짜 신의 한 수.. 따로 브러쉬 안 챙겨도 되고 톡톡 두드리면 끝이라 아침에 시간 단축 제대로 돼요 ㅋㅋ 다크서클이 심한 편이라 웬만한 걸로 안 가려지는데 이건 커버력도 좋고 얇게 발려서 눈가 주름 끼임도 적은 편입니당. 건성이라 뻑뻑할까봐 걱정했는데 각질 부각 없이 잘 쓰고 있어요.","u":"네이버 페이 구매자","d":"2025-12-25 17:40:00","r":0,"p":[]},{"i":2584,"s":5,"t":"턱 쪽에 트러블 자국 때문에 스트레스였는데 커버력 미쳤어요.. 소량만 써도 다 가려짐. 내장 스펀지로 두드리니까 경계도 안 지고 블렌딩 진짜 쉬움. 마스크 써도 잘 안 묻어나서 좋아요. 인생템 등극입니다ㅠ","u":"네이버 페이 구매자","d":"2025-12-25 17:32:00","r":0,"p":[]},{"i":2583,"s":5,"t":"유명하다는 컨실러 다 써봤는데 여기로 정착합니다. 스펀지 팁이 진짜 요물임.. 손에 안 묻히고 밖에서 수정 화장하기 너무 편해요. 지속력도 짱짱하고 색상도 상아빛으로 예쁘게 잘 뽑힌 것 같아요. 21호 쓰는데 화사하게 딱 맞음.","u":"네이버 페이 구매자","d":"2025-12-25 15:56:00","r":0,"p":[]},{"i":2582,"s":5,"t":"눈가 주름 끼임 심해서 웬만하면 컨실러 잘 안 쓰는데 이건 촉촉하게 발리면서 마무리는 깔끔해요. 구름 스킨이라더니 진짜 가벼움. 다크서클 푸른기 잘 잡아주고 위에 파데 올려도 안 밀려요! 건성인데도 안 뜨고 잘 맞네요.","u":"네이버 페이 구매자","d":"2025-12-25 15:08:00","r":0,"p":[]},{"i":2581,"s":5,"t":"지성이라 오후만 되면 컨실러 다 녹아서 없어지는데 이건 진짜 오래가요. 오늘 땀 좀 흘렸는데도 멀쩡해서 놀랐음.. 밀착력 진짜 좋고 얇게 발리는데 잡티는 싹 가려짐. 탐뷰티 처음 사보는데 베이스 맛집인듯? 재구매 의사 있어요.","u":"네이버 페이 구매자","d":"2025-12-25 12:12:00","r":0,"p":[]},{"i":2580,"s":5,"t":"와 이거 진짜 물건이네요. 스펀지 팁 달려있어서 브러쉬나 퍼프 따로 안 꺼내도 되는 게 신세계임. 그냥 콕콕 찍고 슥슥 펴바르면 끝이라 아침에 시간 단축 대박이에요. 커버력도 좋은데 두껍게 안 발려서 데일리로 딱입니다. 다크서클 고민인 분들 강추.","u":"네이버 페이 구매자","d":"2025-12-25 10:39:00","r":0,"p":[]},{"i":2579,"s":5,"t":"탐뷰티 처음 써보는데 기대 이상입니다. 스펀지가 내장돼서 양 조절도 쉽고 얇게 펴 바르기 좋네요. 컨실러 유목민이었는데 여기 정착합니다","u":"네이버 페이 구매자","d":"2025-12-25 10:11:00","r":0,"p":[]},{"i":2578,"s":5,"t":"21호 쿨톤인데 색상 화사하게 잘 맞아요. 바쁜 아침에 손에 묻힐 필요 없이 슥슥 바르고 나가면 끝이라 간편해서 좋아요","u":"네이버 페이 구매자","d":"2025-12-25 09:23:00","r":0,"p":[]},{"i":2577,"s":5,"t":"잡티가 많은 편이라 커버력 중요하게 보는데 이거 진짜 물건이네요 ㅎㅎ 스펀지로 톡톡 두드리면 경계 없이 자연스럽게 블렌딩 됩니다. 재구매 의사 있어요","u":"네이버 페이 구매자","d":"2025-12-25 08:09:00","r":0,"p":[]},{"i":2576,"s":5,"t":"수부지 피부인데 오후에 유분 올라와도 잘 안 무너지고 오래가네요. 밀착력이 좋아서 들뜨지 않고 피부에 착 붙어있는 느낌이라 좋아요.","u":"네이버 페이 구매자","d":"2025-12-25 07:49:00","r":0,"p":[]},{"i":2575,"s":5,"t":"스펀지 팁이 달려있어서 따로 브러쉬 안 챙겨도 돼서 넘 편해요. 다크서클 커버도 잘 되고 지속력도 짱짱합니다. 수정화장용으로 딱이에요","u":"네이버 페이 구매자","d":"2025-12-25 04:19:00","r":0,"p":[]},{"i":2574,"s":5,"t":"탐뷰티 처음 들어봐서 반신반의하며 샀는데 퀄리티 대박이네요. 제형이 꾸덕하지 않고 부드러운데 픽싱되면 딱 고정돼요. 마스크 닿는 부분에 써도 잘 안 벗겨져서 데일리템 등극함.","u":"네이버 페이 구매자","d":"2025-12-25 03:41:00","r":0,"p":[]},{"i":2573,"s":5,"t":"트러블 자국 때문에 스트레스였는데 이거 커버력 미쳤어요.. 컨실러 브러쉬 따로 안 챙겨도 돼서 넘 간편하고 스펀지로 경계 풀어주면 자연스럽게 감쪽같아짐. 21호 웜톤인데 컬러도 칙칙하지 않고 딱 예쁘게 빠졌네요.","u":"네이버 페이 구매자","d":"2025-12-25 03:09:00","r":0,"p":[]},{"i":2572,"s":5,"t":"운동할 때 베이스 다 무너져서 고민하다가 롱웨어라길래 사봤어요. 땀 흘려도 지저분하게 안 무너지고 딱 붙어있네요ㅎㅎ 스펀지 팁이라 양 조절 쉬운 게 신의 한 수인 듯. 잡티 많은 분들 강추요.","u":"네이버 페이 구매자","d":"2025-12-25 03:02:00","r":0,"p":[]},{"i":2571,"s":5,"t":"다크서클 커버 유목민인데 탐뷰티 여기 눕습니다. 눈 밑 주름 끼임 없이 얇게 올라가는데 커버력 무슨 일이죠? 이름처럼 가볍게 밀착돼서 답답한 느낌 1도 없어요. 붉은 기 잡는 데도 최고!","u":"네이버 페이 구매자","d":"2025-12-25 02:47:00","r":0,"p":[]},{"i":2570,"s":5,"t":"손에 컨실러 묻는 거 질색인데 이건 스펀지 내장이라 혁명임.. 그냥 슥 긋고 뒤에 달린 팁으로 톡톡하면 끝이라 너무 편해요. 수부지라 오후 되면 다크서클 내려오는데 이건 지속력도 짱짱해서 수정화장용으로 하나 더 쟁일 예정.","u":"네이버 페이 구매자","d":"2025-12-24 21:05:00","r":0,"p":[]},{"i":2569,"s":5,"t":"와 이거 왜 안 유명해요? 올영 갔다가 테스트 해보고 밀착력 미쳐서 바로 집어옴;;; 파데 안 쓰고 이거로만 대충 베이스 했는데 피부 좋아 보인다는 소리 들음. 제발 단종시키지 마세요 ㅠ","u":"네이버 페이 구매자","d":"2025-12-24 19:12:00","r":0,"p":[]},{"i":2568,"s":5,"t":"커버부터 블렌딩까지 한 번에 된다고 해서 샀는데 바쁜 아침에 시간 단축 대박임ㅋㅋ 근데 스펀지 팁 계속 쓰다 보면 위생이 좀 걱정되긴 하는데.. 뭐 편하니까 흐린 눈 하고 씁니다. 밀착력은 인정.","u":"네이버 페이 구매자","d":"2025-12-24 18:57:00","r":0,"p":[]},{"i":2567,"s":5,"t":"21호 쿨톤인데 컬러가 진짜 예쁘게 빠졌어요. 너무 노랗지도 않고 딱 맑은 상아색 느낌? 잡티 가린다고 두껍게 올리면 텁텁해 보이는데 이건 얇게 발리면서 커버력은 중상 이상이라 신기함.. 탐뷰티 처음 써보는데 괜찮네요.","u":"네이버 페이 구매자","d":"2025-12-24 14:12:00","r":0,"p":[]},{"i":2566,"s":5,"t":"수부지 피부라 오후 되면 유분 폭발해서 베이스 다 뜨는데 이건 픽싱이 빨라서 그런지 짱짱하게 버티네요. 땀 흘려도 잘 안 지워져서 이번 여름은 이걸로 정착할 듯. 대신 픽싱 빠르니까 바르고 바로 블렌딩 해줘야 해요.","u":"네이버 페이 구매자","d":"2025-12-24 14:07:00","r":0,"p":[]},{"i":2565,"s":5,"t":"손에 뭐 묻는 거 딱 질색인데 스펀지 팁 달려있어서 세상 편해요. 그냥 슥 긋고 톡톡 두드리면 끝남. 다크서클 심해서 샀는데 주름 끼임 없이 얇게 핏되면서 가려지네요. 지속력도 아침에 바르고 나가서 저녁까지 멀쩡했어요.","u":"네이버 페이 구매자","d":"2025-12-24 12:26:00","r":0,"p":[]},{"i":2564,"s":5,"t":"수정 화장용으로 들고 다니기 너무 편해요. 밖에서 손으로 펴 바르기 찝찝한데 내장 스펀지로 두드리면 끝나니까 위생적이고 좋네요. 커버력이 워낙 좋아서 파데 프리할 때 잡티 부분만 이걸로 가려도 피부 좋아 보여요.","u":"네이버 페이 구매자","d":"2025-12-24 12:10:00","r":0,"p":[]},{"i":2563,"s":5,"t":"탐뷰티 신상이라 반신반의하면서 샀는데 기대 이상입니다. 스펀지 팁이 달려있는 게 진짜 신의 한 수인 듯.. 손 안 대고 톡톡 두드리면 트러블 자국이랑 붉은 기 순삭이에요. 마스크 써도 잘 안 묻어나서 요즘 데일리템 등극했습니다 👍","u":"네이버 페이 구매자","d":"2025-12-24 12:04:00","r":0,"p":[]},{"i":2562,"s":5,"t":"다크서클이 심해서 컨실러 유목민이었는데 여기에 정착할 것 같아요.. 이름처럼 가볍게 올라가는데 커버력은 확실하네요? 두껍게 발리면 눈가 주름 끼임 심한데 이건 얇게 발려서 좋아요. 쿨톤인데 색상 화사하게 잘 빠졌습니다.","u":"네이버 페이 구매자","d":"2025-12-24 09:56:00","r":0,"p":[]},{"i":2561,"s":5,"t":"파워 지성이라 오후만 되면 유분 때문에 컨실러 다 지워지는데 이건 밀착력이 좋아서 그런지 짱짱하게 버티네요. 잡티 커버력은 말할 것도 없고, 특히 스펀지로 두드리면 블렌딩이 자연스럽게 돼서 경계 안 지는 게 맘에 듭니다. 재구매 의사 있어요.","u":"네이버 페이 구매자","d":"2025-12-24 09:33:00","r":0,"p":[]},{"i":2560,"s":5,"t":"스펀지 팁이 내장되어 있어서 따로 브러쉬나 퍼프 안 챙겨도 되는 게 진짜 편해요. 바쁜 아침에 다크서클 슥슥 가리고 톡톡 두드리면 끝이라 준비 시간 엄청 줄었습니다. 픽싱이 빠른 편이라 바르고 바로 블렌딩 해주는 게 좋아요. 21호 쓰는데 컬러 자연스럽게 잘 맞습니다.","u":"네이버 페이 구매자","d":"2025-12-24 09:31:00","r":0,"p":[]},{"i":2559,"s":5,"t":"피부가 얇아서 컨실러 쓰면 텁텁해 보이는데 이건 얇게 밀착돼서 자연스러워요. 스펀지 팁으로 톡톡 두드리면 모공도 어느 정도 가려지네요. 수정 화장용으로 들고 다니기 편해요.","u":"네이버 페이 구매자","d":"2025-12-24 07:02:00","r":0,"p":[]},{"i":2558,"s":5,"t":"내돈내산 솔직 후기입니다. 매트하게 픽싱되는 편이라 기초 탄탄히 하고 바르는 게 좋아요. 잡티 커버는 확실히 잘 되고 지속력도 짱짱합니다. 스펀지 팁 달려있는 게 신의 한 수..","u":"네이버 페이 구매자","d":"2025-12-24 05:20:00","r":0,"p":[]},{"i":2557,"s":5,"t":"다크서클이 심해서 웬만한 컨실러 다 써봤는데 커버력 상급이에요. 내장 스펀지로 경계선 없이 펴 바르기 좋고 주름 끼임도 적은 편. 다만 양 조절은 살짝 필요해요.","u":"네이버 페이 구매자","d":"2025-12-24 04:30:00","r":0,"p":[]},{"i":2556,"s":5,"t":"지성이라 시간 지나면 코 옆 끼임 심한데 이건 밀착력이 좋아서 그런지 오래 가요. 땀 흘려도 지저분하게 안 무너져서 여름까지 잘 쓸 것 같아요. 스펀지로 펴 바르기 쉬워서 곰손들에게 강추!","u":"네이버 페이 구매자","d":"2025-12-24 03:31:00","r":0,"p":[]},{"i":2555,"s":5,"t":"탐뷰티 처음 써보는데 스펀지 팁이 진짜 편하네요. 손에 안 묻히고 톡톡 두드리면 블렌딩까지 한 번에 돼서 아침에 시간 없을 때 최고예요. 커버력도 좋은데 두껍게 안 발려서 다크서클용으로 딱입니다.","u":"네이버 페이 구매자","d":"2025-12-24 01:29:00","r":0,"p":[]},{"i":2554,"s":5,"t":"여드름 흉터 때문에 커버력 젤 중요하게 보는데 웬만한 파데보다 나아요. 스펀지가 내용물을 좀 먹는 느낌은 있는데 그만큼 얇게 밀착시켜줘서 두꺼운 화장 느낌 안 납니다. 지속력도 좋아서 수정 화장 거의 안 했어요.","u":"네이버 페이 구매자","d":"2025-12-24 00:53:00","r":0,"p":[]},{"i":2553,"s":5,"t":"탐뷰티? 처음 들어보는 브랜드라 반신반의하면서 샀는데 기대 이상이에요. 똥손이라 컨실러 쓰면 경계 지는데 이건 내장 팁으로 슥슥 문지르면 자연스럽게 블렌딩 돼요. 색상도 21호 쓰는데 화사하게 잘 맞습니다 ㅎㅎ","u":"네이버 페이 구매자","d":"2025-12-24 00:34:00","r":0,"p":[]},{"i":2552,"s":5,"t":"지성이라 오후만 되면 베이스 다 무너지는데 이건 롱웨어라 그런지 짱짱하게 버티네요. 잡티 커버하려고 샀는데 얇게 발리면서도 가릴 건 다 가려줘서 놀랐어요. 스펀지 팁 따로 세척하기 귀찮긴 한데 커버력 좋아서 감안하고 씁니다.","u":"네이버 페이 구매자","d":"2025-12-23 23:14:00","r":0,"p":[]},{"i":2551,"s":5,"t":"다크서클이 심한 편이라 컨실러 유목민인데 이거 요물이네요. 이름처럼 가볍게 올라가서 눈가 주름 끼임이 거의 없어요. 스펀지로 펴바르니까 밀착도 잘 되고 오후 돼도 칙칙해지는 거 없어서 만족합니다. 재구매 의사 있어요.","u":"네이버 페이 구매자","d":"2025-12-23 22:51:00","r":0,"p":[]},{"i":2550,"s":5,"t":"인스타 광고 보고 샀는데 생각보다 물건이네요. 보통 팟타입 쓰다가 먼지 끼는 거 싫어서 이걸로 갈아탔는데, 뒤에 달린 스펀지팁이 진짜 편해요. 손에 안 묻히고 톡톡 두드리면 끝나니까 바쁜 아침에 최고입니다. 커버력도 중상 정도는 되는 듯?","u":"네이버 페이 구매자","d":"2025-12-23 18:42:00","r":0,"p":[]},{"i":2549,"s":5,"t":"수정 화장용으로 샀는데 휴대가 간편해서 너무 좋아요. 스펀지 따로 안 들고 다녀도 되는 게 신의 한 수.. 밖에서 톡톡 두드리면 아침 화장처럼 복구됩니다 ㅋㅋ 건성인데도 갈라짐 없이 촉촉하게 마무리돼서 만족스러워요!","u":"네이버 페이 구매자","d":"2025-12-23 18:41:00","r":0,"p":[]},{"i":2548,"s":5,"t":"트러블 자국 때문에 스트레스였는데 이거 쓰고 광명 찾음요 ㅠㅠ 컨실러 유목민이었는데 여기 정착하려구요. 스펀지로 두드리니까 얇게 밀착돼서 원래 내 피부 좋은 것처럼 보여요. 땀 흘려도 안 지워져서 운동할 때도 바르고 갑니다 굿굿.","u":"네이버 페이 구매자","d":"2025-12-23 16:10:00","r":0,"p":[]},{"i":2547,"s":5,"t":"파데프리 메이크업 할 때 이것만 씁니다. 이름대로 클라우드처럼 가볍게 올라가는데 커버력은 미쳤어요.. 스펀지 팁이라 양 조절 쉽고 콧볼 붉은기 커버할 때 짱 편함! 두껍게 발리는 거 싫어하시는 분들께 강추드려요.","u":"네이버 페이 구매자","d":"2025-12-23 14:27:00","r":0,"p":[]},{"i":2546,"s":5,"t":"수부지 피부라 오후 되면 코 옆이랑 다크닝 심하게 오는데 이건 밀착력이 좋아서 그런지 무너짐이 거의 없어요. 유분기 올라와도 더럽게 안 무너지고 예쁘게 광나는 정도? 스펀지로 펴 바르니까 손에 안 묻어서 넘 편하고 잡티도 감쪽같이 가려집니다 ㅎㅎ 인생 컨실러 찾았어요.","u":"네이버 페이 구매자","d":"2025-12-23 13:12:00","r":0,"p":[]},{"i":2545,"s":5,"t":"탐뷰티 처음 들어봐서 반신반의하며 샀는데 대박이네요.. 내장 스펀지가 진짜 요물입니다 따로 브러쉬 안 챙겨도 되고 톡톡 두드리면 커버 끝이라 출근 시간 단축됐어요 ㅋㅋ 다크서클 심한 편인데 얇게 발리면서도 커버력 짱짱합니다! 다 쓰면 또 살 거예요.","u":"네이버 페이 구매자","d":"2025-12-23 12:56:00","r":0,"p":[]},{"i":2544,"s":5,"t":"커버력이랑 지속력 둘 다 잡은 제품 찾다가 정착했어요.. 톡 찍고 내장 팁으로 펴 바르면 끝이라 곰손한테도 강추. 붉은 기 커버에 직빵입니다.","u":"네이버 페이 구매자","d":"2025-12-23 12:50:00","r":0,"p":[]},{"i":2543,"s":5,"t":"건성이라 컨실러 잘못 쓰면 눈가 쩍쩍 갈라지는데 이건 얇게 착 붙네요. 스펀지로 살살 펴 바르면 경계 안 지고 자연스러워요. 클라우드 스킨이라는 이름처럼 가벼움 ㅎ","u":"네이버 페이 구매자","d":"2025-12-23 11:47:00","r":0,"p":[]},{"i":2542,"s":5,"t":"내돈내산 후기입니다. 여행 갈 때 브러쉬 챙기기 귀찮아서 샀는데 스펀지 일체형이라 수정 화장할 때 진짜 꿀템임! 뭉침 없이 얇게 발려서 답답하지 않아요. 재구매 의사 있음.","u":"네이버 페이 구매자","d":"2025-12-23 11:22:00","r":0,"p":[]},{"i":2541,"s":5,"t":"수부지 피부인데 이거 요물이에요. 땀이랑 유분에 강해서 마스크 써도 잘 안 지워짐. 커버력은 말해 뭐해 잡티 싹 가려져요. 탐뷰티 베이스 처음 써보는데 꽤 괜찮네요.","u":"네이버 페이 구매자","d":"2025-12-23 08:48:00","r":0,"p":[]},{"i":2540,"s":5,"t":"스펀지 팁이 신의 한 수네요.. 다크서클 커버할 때 브러쉬 따로 안 써도 돼서 세상 편해요. 손에 안 묻히고 톡톡 두드리면 끝나니까 아침에 시간 단축 됨! 밀착력도 좋아서 오후까지 안 뜨고 멀쩡합니다.","u":"네이버 페이 구매자","d":"2025-12-23 08:40:00","r":0,"p":[]},{"i":2539,"s":5,"t":"수정 화장용으로 들고 다니기 딱 좋은 사이즈예요. 밖에서 손에 뭐 묻히기 싫은데 팁으로 슥슥하면 끝나니까 위생적이고 편함ㅠㅠ 커버력은 말모.. 소량으로도 잡티 순삭 가능합니다 굿굿","u":"네이버 페이 구매자","d":"2025-12-23 08:26:00","r":0,"p":[]},{"i":2538,"s":5,"t":"다크서클이 심해서 컨실러 유목민이었는데 여기에 정착합니당. 스펀지로 톡톡 두드리면 경계 안 지고 자연스럽게 커버돼요. 눈가 주름 끼임 걱정했는데 얇게 발려서 그런지 각질 부각 없이 매끈해요!","u":"네이버 페이 구매자","d":"2025-12-23 06:50:00","r":0,"p":[]},{"i":2537,"s":5,"t":"파워 지성이라 오후만 되면 베이스 다 녹아내리는데 이건 짱짱하게 버티네요. 유분기 올라와도 더럽게 무너지는 게 아니라 예쁘게 섞이는 느낌? 땀 많이 흘리는 날에도 살아남았어요ㅋㅋ 지속력 인정합니다.","u":"네이버 페이 구매자","d":"2025-12-23 06:25:00","r":0,"p":[]},{"i":2536,"s":5,"t":"탐뷰티 신상이라 궁금해서 사봤는데 기대 이상이네요.. 이름처럼 가볍게 올라가는데 커버력은 확실해요. 트러블 자국 많은 편인데 컨실러 하나로 피부 표현 깔끔해짐! 밀착력 좋아서 마스크에도 잘 안 묻어납니다.","u":"네이버 페이 구매자","d":"2025-12-23 06:13:00","r":0,"p":[]},{"i":2535,"s":5,"t":"아침에 바빠 죽겠는데 스펀지 팁 달려있어서 진짜 편해요ㅋㅋ 그냥 콕 찍고 그 팁으로 두드리면 끝이라 손에 안 묻어서 좋음. 다크서클 커버도 잘 되고 점심 지나도 안 무너져서 놀랐어요. 재구매 의사 200%","u":"네이버 페이 구매자","d":"2025-12-23 04:41:00","r":0,"p":[]},{"i":2534,"s":5,"t":"트러블 자국 때문에 스트레스였는데 커버력 진짜 인정.. 스펀지로 톡톡 두드리면 경계 없이 자연스럽게 가려져요. 마무리는 보송해서 파우더 따로 안 해도 될 것 같아요.","u":"네이버 페이 구매자","d":"2025-12-23 00:53:00","r":0,"p":[]},{"i":2533,"s":5,"t":"21호 쿨톤인데 컬러가 화사하게 잘 빠졌어요. 원래 쓰던 거 다 써서 급하게 샀는데 스펀지로 블렌딩하니까 자국도 안 남고 자연스럽네요. 가성비 최고인 듯.","u":"네이버 페이 구매자","d":"2025-12-22 23:33:00","r":0,"p":[]},{"i":2532,"s":5,"t":"유분기 많은 지성 피부라 컨실러 금방 무너지는 편인데 이건 롱웨어라 그런지 하루 종일 짱짱해요. 탐뷰티 처음 써보는데 잡티 커버력 진짜 미쳤음..👍","u":"네이버 페이 구매자","d":"2025-12-22 20:42:00","r":0,"p":[]},{"i":2531,"s":5,"t":"눈가 피부가 얇아서 컨실러 잘못 쓰면 주름에 다 끼는데 이건 얇게 밀착돼서 좋아요. 다크서클 커버도 잘 되고 시간 지나도 들뜸 없이 유지되네요. 건성분들 추천해요.","u":"네이버 페이 구매자","d":"2025-12-22 18:59:00","r":0,"p":[]},{"i":2530,"s":5,"t":"스펀지 팁이 달려있어서 손에 안 묻히고 슥슥 바르기 편해요. 아침에 시간 없을 때 다크서클 가리기 딱 좋음. 커버력도 기대 이상이라 재구매 의사 있어요.","u":"네이버 페이 구매자","d":"2025-12-22 16:54:00","r":0,"p":[]},{"i":2529,"s":5,"t":"건성이라 컨실러 잘못 쓰면 눈가 주름에 다 끼는데 이건 촉촉하게 발리면서 마무리는 세미매트해서 딱 좋아요. 트러블 자국도 깔끔하게 가려지고 무엇보다 지속력이 대박임.. 수정화장 귀찮은 분들께 추천드려요 👍","u":"네이버 페이 구매자","d":"2025-12-22 16:28:00","r":0,"p":[]},{"i":2528,"s":5,"t":"sns에서 핫하길래 반신반의하며 샀는데 생각보다 훨씬 좋아요. 보통 컨실러는 브러쉬 없으면 두껍게 발리는데 이건 내장 팁으로 톡톡하면 끝이라 편해요. 끼임도 거의 없고 얇게 착 붙어서 피부 좋아보임. 쿨톤 21호 쓰는데 컬러도 화사하니 딱 맞아요.","u":"네이버 페이 구매자","d":"2025-12-22 12:25:00","r":0,"p":[]},{"i":2527,"s":5,"t":"내돈내산 후기입니다. 일단 스펀지가 달려있어서 파우치 부피 줄어서 너무 좋구요. 커버력이 높은데 두껍게 안 발려서 신기해요! 급할 때 슥 그어서 스펀지로 펴주면 베이스 끝이라 요즘 이것만 씁니다.","u":"네이버 페이 구매자","d":"2025-12-22 10:01:00","r":0,"p":[]},{"i":2526,"s":5,"t":"지성이라 오후만 되면 잡티 다 드러나는데 탐뷰티껀 지속력 인정이요. 땀 흘려도 안 무너지고 짱짱하게 버티네요 ㅋㅋ 스펀지로 펴 바르니까 결 자국도 안 남고 블렌딩 진짜 쉬움.. 똥손들은 무조건 이거 사세요.","u":"네이버 페이 구매자","d":"2025-12-22 09:13:00","r":0,"p":[]},{"i":2525,"s":5,"t":"다크서클 때문에 컨실러 유목민이었는데 이거 물건이네요.. 뒤에 달린 스펀지 팁이 진짜 편해요. 손에 안 묻히고 톡톡 두드리면 얇게 밀착되는데 커버력 미쳤음. 아침에 바르고 나가도 저녁까지 다크 안 내려와요. 재구매 의사 100%입니다.","u":"네이버 페이 구매자","d":"2025-12-22 08:53:00","r":0,"p":[]},{"i":2524,"s":5,"t":"19-21호 사이 쿨톤인데 색상 화사하게 잘 빠졌어요. 붉은기 커버 잘 되고 무엇보다 땀 흘려도 안 지워져서 운동갈 때도 바름ㅋㅋ 스펀지 팁이라 수정하기도 짱 편해요. 고민 말고 사세요.","u":"네이버 페이 구매자","d":"2025-12-22 04:41:00","r":0,"p":[]},{"i":2523,"s":5,"t":"올영 랭킹 보고 샀다가 정착합니다.. 스펀지 달린 컨실러 몇 개 써봤는데 탐뷰티께 제일 탄탄한 것 같아요. 피부에 착 붙는 느낌? 밀착커버라는 말이 딱 맞음. 두껍게 안 발리고 얇게 레이어링 돼서 답답한 느낌도 없어요. 세일할 때 쟁여둬야겠어요.","u":"네이버 페이 구매자","d":"2025-12-22 04:31:00","r":0,"p":[]},{"i":2522,"s":5,"t":"여드름 흉터 때문에 커버력 중요하게 생각하는데, 이거 웬만한 파데보다 낫네요. 팁으로 콕 찍어놓고 스펀지로 펴 바르니까 경계 안 지고 감쪽같이 가려져요. 지성이라 오후 되면 기름 올라오면서 베이스 무너지는 편인데 이건 롱웨어라 그런지 저녁까지 짱짱하게 버티네요. 지속력 중요하신 분들 강추👍","u":"네이버 페이 구매자","d":"2025-12-22 04:07:00","r":0,"p":[]},{"i":2521,"s":5,"t":"21호 건성 피부입니다. 평소에 컨실러 쓰면 눈가 주름에 끼어서 잘 안 쓰는데, 이건 '클라우드' 이름값 하네요. 제형이 되게 가볍게 올라가요. 다크서클이 푸른 편인데 컬러가 잘 잡혀서 칙칙해 보이지 않아서 좋아요. 스펀지로 두드리니까 블렌딩도 자연스럽고 수정 화장할 때도 들뜸 없어서 파우치 필수템 됐어요.","u":"네이버 페이 구매자","d":"2025-12-21 22:35:00","r":0,"p":[]},{"i":2520,"s":5,"t":"탐뷰티 처음 들어보는 브랜드라 반신반의했는데 진짜 물건이네요. 스펀지 팁 내장된 게 신의 한 수인 듯.. 손에 안 묻히고 슥슥 펴 바르면 끝나서 아침에 시간 절약 대박이에요. 다크서클도 잘 가려지고 밀착력 좋아서 마스크 써도 잘 안 묻어나요. 재구매 의사 있음!","u":"네이버 페이 구매자","d":"2025-12-21 22:29:00","r":0,"p":[]},{"i":2519,"s":5,"t":"21호 쓰는데 컬러가 누렇지 않고 상아빛으로 예쁘게 뽑혔어요. 잡티 커버하려고 샀는데 밀착력 대박임.. 스펀지로 펴 바르고 픽싱되면 문질러도 안 지워져요. 땀 흘려도 그대로라 여름용 컨실러로 정착합니다.","u":"네이버 페이 구매자","d":"2025-12-21 21:44:00","r":0,"p":[]},{"i":2518,"s":5,"t":"커버력은 진짜 인정.. 붉은기랑 여드름 흉터 순삭이에요. 근데 내장 스펀지는 편하긴 한데 위생 관리가 좀 걱정되긴 하네요 ㅠ 뚜껑 닫을 때 묻어남 주의해야 함. 그래도 제품력은 좋아서 다 쓰면 또 살 듯.","u":"네이버 페이 구매자","d":"2025-12-21 20:19:00","r":0,"p":[]},{"i":2517,"s":5,"t":"수부지 피부라 오후 되면 베이스 다 무너지는데 이건 픽싱이 빨라서 그런지 짱짱하게 버티네요. 유분기 올라와도 더럽게 무너지지 않아서 좋음. 다만 양 조절 잘못하면 좀 두꺼워질 수 있으니 소량만 찍어서 스펀지로 펴주세요.","u":"네이버 페이 구매자","d":"2025-12-21 18:42:00","r":0,"p":[]},{"i":2516,"s":5,"t":"건성이라 눈가 주름 끼임 걱정했는데 이름처럼 가볍게 발려서 놀랐어요. 다크서클 커버용으로 샀는데 두껍지 않게 촥 밀착돼서 자연스러워요. 스펀지로 톡톡 두드리면 블렌딩도 쉬워서 곰손들에게 추천!","u":"네이버 페이 구매자","d":"2025-12-21 14:56:00","r":0,"p":[]},{"i":2515,"s":5,"t":"스펀지 팁이 일체형이라 손에 안 묻히고 슥슥 바르기 너무 편해요. 바쁜 아침에 짱임.. 커버력도 기대 안 했는데 다크서클 푸른기 잘 가려지네요. 지속력도 꽤 괜찮아서 점심 먹고 나서도 수정 화장 딱히 필요 없었어요.","u":"네이버 페이 구매자","d":"2025-12-21 14:38:00","r":0,"p":[]},{"i":2514,"s":5,"t":"21호 쿨톤인데 컬러가 누렇지 않고 상아빛으로 예쁘게 잘 뽑혔어요. 밖에서 수정 화장할 때 브러쉬나 퍼프 따로 챙기기 귀찮은데 이건 스펀지가 달려있어서 휴대용으로 최고예요. 코 옆 붉은기랑 입가 정리하기도 너무 편하고 좋네요.","u":"네이버 페이 구매자","d":"2025-12-21 13:25:00","r":0,"p":[]},{"i":2513,"s":5,"t":"이름처럼 구름같이 가볍게 발리는데 커버력은 확실하네요. 두껍게 올라가는 느낌 싫어해서 평소에 컨실러 잘 안 쓰는데, 이건 얇게 착 붙어서 답답함이 없어요. 붉은 트러블 자국도 깔끔하게 가려져서 요즘 파우치 필수템 됐습니당","u":"네이버 페이 구매자","d":"2025-12-21 13:22:00","r":0,"p":[]},{"i":2512,"s":5,"t":"아침에 출근할 때 슥 긋고 내장 스펀지로 펴 바르면 끝이라 화장 시간이 확 줄었어요. 보통 일체형 스펀지는 좀 뻑뻑할 때가 많은데 이건 부드럽게 블렌딩 잘 돼서 초보자분들도 쓰기 좋을 것 같아요. 다 쓰면 재구매 의사 100%입니다.","u":"네이버 페이 구매자","d":"2025-12-21 12:22:00","r":0,"p":[]},{"i":2511,"s":5,"t":"지성이라 오후만 되면 유분 때문에 베이스가 다 무너지는데 이건 롱웨어라 그런지 지속력이 짱짱하네요. 잡티 가리려고 샀는데 밀착력이 좋아서 파데 대신 이걸로 얇게 전체적으로 깔아도 될 것 같아요. 땀에도 강해서 여름까지 정착할 듯!","u":"네이버 페이 구매자","d":"2025-12-21 08:06:00","r":0,"p":[]},{"i":2510,"s":5,"t":"탐뷰티 컨실러 궁금해서 사봤는데 스펀지 팁이 진짜 신의 한 수네요.. 손에 묻힐 필요 없이 톡톡 두드리면 끝나니까 너무 편해요. 다크서클이 심한 편이라 건조하면 주름 끼임 걱정되는데, 이건 촉촉하게 발리면서 마무리는 깔끔해서 눈가 커버용으로 딱입니다.","u":"네이버 페이 구매자","d":"2025-12-21 07:27:00","r":0,"p":[]},{"i":2509,"s":5,"t":"원래 컨실러 브러쉬 따로 쓰는데 이건 내장 스펀지가 쫀쫀해서 그냥 써도 퀄리티 높게 나옴. 요즘 파데프리 할 때 잡티만 콕콕 찍어서 펴 바르면 피부 엄청 좋아 보여요. 얇게 발리는데 커버력은 확실해서 요즘 이것만 손이 감.","u":"네이버 페이 구매자","d":"2025-12-20 22:22:00","r":0,"p":[]},{"i":2508,"s":5,"t":"SNS 광고 보고 반신반의하며 샀는데 생각보다 퀄리티 좋아서 당황; 21호 쿨톤인데 색상 화사하게 잘 빠졌고 잿빛 안 돌아서 좋아요. 스펀지가 내용물을 좀 먹긴 하는데 블렌딩이 워낙 잘돼서 용서됨. 밀착력 좋아서 마스크에도 거의 안 묻어나요.","u":"네이버 페이 구매자","d":"2025-12-20 21:16:00","r":0,"p":[]},{"i":2507,"s":5,"t":"유분 폭발하는 지성인데 지속력 미쳤음... 점심 먹고 거울 봤는데 잡티 가린 거 그대로라 놀랐어요. 탐뷰티 처음 써보는데 베이스 맛집인 듯? 스펀지 팁 내장이라 밖에서 수정할 때도 쿠션 안 꺼내고 이걸로 톡톡하면 끝나요. 잡티 많은 분들 강추.","u":"네이버 페이 구매자","d":"2025-12-20 21:14:00","r":0,"p":[]},{"i":2506,"s":5,"t":"건성 김미연이라 컨실러 쓰면 눈가 주름에 끼는 거 스트레스였는데 이건 이름처럼 가볍게 밀착되네요. 스펀지로 펴 바르니까 경계 안 지고 자연스러움. 다크서클 커버용으로 샀는데 촉촉하면서도 고정력 있어서 만족해요. 다 쓰면 재구매 의사 있음.","u":"네이버 페이 구매자","d":"2025-12-20 21:11:00","r":0,"p":[]},{"i":2505,"s":5,"t":"스펀지 팁 달려있는 게 신의 한 수... 손에 뭐 묻히기 싫어서 샀는데 톡톡 찍고 바로 블렌딩하면 돼서 너무 편해요. 아침에 시간 없을 때 퀵메이크업용으로 딱임. 커버력도 기대 이상이라 다크서클이랑 코 옆 붉은기 싹 가려집니다. 지속력도 좋아서 오후 돼도 안 무너짐!","u":"네이버 페이 구매자","d":"2025-12-20 17:48:00","r":0,"p":[]},{"i":2504,"s":5,"t":"스펀지 내장된 게 진짜 요물입니다.. 콕 찍고 뒤로 슥슥 펴주면 경계 안 지고 자연스러워요. 다만 양 조절은 필수인 듯. 너무 많이 바르면 두꺼워질 수 있으니 소량만 써도 충분해요. 밀착력 하나는 인정.","u":"네이버 페이 구매자","d":"2025-12-20 16:15:00","r":0,"p":[]},{"i":2503,"s":5,"t":"원래 팟 타입 쓰다가 먼지 붙는 거 싫어서 갈아탔어요. 팁이랑 스펀지가 같이 있으니까 블렌딩하기 너무 쉽네요. 21호 쓰는데 컬러도 화사하게 잘 빠졌고 붉은 기 커버에 탁월합니다. 다 쓰면 재구매 의사 있어요.","u":"네이버 페이 구매자","d":"2025-12-20 14:43:00","r":0,"p":[]},{"i":2502,"s":5,"t":"지성이라 오후만 되면 베이스 다 무너지는데 이건 롱웨어라 그런지 짱짱하게 버티네요? 땀 흘려도 지저분하게 안 지워져서 수정 화장 횟수가 줄었어요. 스펀지 팁 따로 안 챙겨 다녀도 돼서 파우치 가벼워짐! 굳굳.","u":"네이버 페이 구매자","d":"2025-12-20 14:16:00","r":0,"p":[]},{"i":2501,"s":5,"t":"다크서클이 심해서 웬만한 컨실러는 다 써봤는데 탐뷰티 거 얇게 발리면서 커버 잘 되네요. 눈가 주름 끼임 걱정했는데 스펀지로 펴 바르니까 밀착력 있게 딱 붙어요. 오후 되어도 갈라짐 없어서 만족합니다.","u":"네이버 페이 구매자","d":"2025-12-20 13:05:00","r":0,"p":[]},{"i":2500,"s":5,"t":"인스타 보고 영업 당해서 샀는데 이거 진짜 편해요. 뒤에 달린 스펀지 팁이 신의 한 수... 손에 안 묻히고 톡톡 두드리면 끝나서 바쁜 아침에 최고입니다. 커버력도 중상 정도라 잡티 가리기 좋아요.","u":"네이버 페이 구매자","d":"2025-12-20 11:50:00","r":0,"p":[]},{"i":2499,"s":5,"t":"두껍게 발리는 거 딱 질색인데 클라우드란 이름답게 가볍게 밀착돼요. 홍조랑 여드름 흉터 싹 가려줘서 오늘 피부 좋아 보인다는 소리 들었어요👍 밀착력이 좋아서 마스크에도 잘 안 묻어나서 만족합니다","u":"네이버 페이 구매자","d":"2025-12-20 10:53:00","r":0,"p":[]},{"i":2498,"s":5,"t":"와 진짜 편해요ㅠㅠ 따로 퍼프나 브러쉬 안 챙겨도 돼서 파우치 부피 확 줄어듦! 잡티 위에 콕 찍고 뒤에 달린 스펀지로 블렌딩해주면 경계 1도 안 남고 자연스럽게 가려져요. 21호 쿨톤인데 컬러도 화사하게 잘 빠졌네요","u":"네이버 페이 구매자","d":"2025-12-20 10:27:00","r":0,"p":[]},{"i":2497,"s":5,"t":"지성 피부라 오후만 되면 유분 때문에 베이스 다 무너지는데 이건 롱웨어라 그런지 짱짱하게 버티네요ㅋㅋ 수정 화장할 때도 내장 스펀지로 쓱 닦고 다시 덮어주면 감쪽같습니다. 잡티 커버는 기본이고 지속력 대박이에요","u":"네이버 페이 구매자","d":"2025-12-20 09:47:00","r":0,"p":[]},{"i":2496,"s":5,"t":"눈가 주름 끼임 때문에 웬만한 컨실러는 다 뜨는데 이건 촉촉하게 발리면서 픽싱은 확실하네요? 다크서클 커버용으로 샀는데 텁텁하지 않고 진짜 얇게 올라가서 놀랐어요. 내돈내산인데 다 쓰면 재구매 의사 200% 있음","u":"네이버 페이 구매자","d":"2025-12-20 07:23:00","r":0,"p":[]},{"i":2495,"s":5,"t":"탐뷰티 처음 들어보는 브랜드라 반신반의하면서 샀는데 진짜 물건이네요.. 스펀지 팁이 달려있어서 손에 묻힐 필요 없이 톡톡 두드리면 끝이라 너무 편해요. 아침에 바쁠 때 이거 하나면 베이스 뚝딱입니다. 커버력도 좋아서 컨실러 유목민 생활 청산할 듯요","u":"네이버 페이 구매자","d":"2025-12-20 04:05:00","r":0,"p":[]},{"i":2494,"s":5,"t":"똥손이라 컨실러 쓰면 항상 경계 남는데, 이건 뒤에 달린 스펀지로 톡톡 두드리면 자연스럽게 블렌딩돼요. 급하게 화장할 때 최고입니다.","u":"네이버 페이 구매자","d":"2025-12-20 03:55:00","r":0,"p":[]},{"i":2493,"s":5,"t":"광고 보고 반신반의하면서 샀는데 기대 이상이에요. 피부에 쫀쫀하게 달라붙어서 땀 흘려도 잘 안 지워지네요. 여름까지 쭉 쓸 것 같습니다.","u":"네이버 페이 구매자","d":"2025-12-20 03:38:00","r":0,"p":[]},{"i":2492,"s":5,"t":"다크서클이 심한 편이라 커버력 중요하게 생각하는데, 두껍지 않게 가려져서 좋아요. 건조하지 않고 얇게 발려서 눈가 주름 끼임도 거의 없네요 ㅎㅎ","u":"네이버 페이 구매자","d":"2025-12-20 01:50:00","r":0,"p":[]},{"i":2491,"s":5,"t":"스펀지 내장된 게 진짜 신의 한 수... 브러쉬 따로 안 챙겨도 돼서 수정 화장할 때 너무 편해요. 잡티도 잘 가려지고 밀착력 대박입니다. 다 쓰면 또 살 거예요!","u":"네이버 페이 구매자","d":"2025-12-20 01:06:00","r":0,"p":[]},{"i":2490,"s":5,"t":"지성이라 오후 되면 베이스 다 무너지는데 이건 픽싱이 빨라서 오래 가요. 스펀지 팁이 달려있어서 손 안 대고 쓱쓱 바르기 편합니다. 다크서클 커버용으로 샀는데 아주 만족해요.","u":"네이버 페이 구매자","d":"2025-12-19 21:37:00","r":0,"p":[]},{"i":2489,"s":5,"t":"솔직히 반신반의하면서 샀는데 기대 이상이에요. 꾸덕한 제형 아니고 얇게 발리는데 픽싱되면 딱 고정돼요. 내장 스펀지가 생각보다 쫀쫀해서 놀랐음. 코 옆 붉은 기 커버할 때도 좋고.. 다만 양 조절은 필수! 너무 많이 바르면 두꺼워질 수 있으니 소량만 톡 찍어서 펴 바르세요 ✨","u":"네이버 페이 구매자","d":"2025-12-19 21:21:00","r":0,"p":[]},{"i":2488,"s":5,"t":"21호 쿨톤인데 컬러 딱 자연스럽게 화사해져요. 잡티 커버 잘 되고 밀착력 굿굿. 스펀지 팁이 있어서 여행 갈 때 파우치 줄이기 좋을 것 같아요.","u":"네이버 페이 구매자","d":"2025-12-19 19:55:00","r":0,"p":[]},{"i":2487,"s":5,"t":"파워 지성이라 오후만 되면 다크닝 오고 무너지는데 이건 지속력 대박이네요. 아침에 바르고 땀 흘렸는데도 거의 그대로라 놀랐어요.. 스펀지 팁 내장된 게 진짜 신의 한 수. 밖에서 수정 화장할 때도 쿠션 안 쓰고 이걸로 슥슥 하면 되니까 짱편해요.","u":"네이버 페이 구매자","d":"2025-12-19 13:00:00","r":0,"p":[]},{"i":2486,"s":5,"t":"눈가 주름 끼임 때문에 컨실러 유목민이었는데 탐뷰티 거 쓰고 정착할 듯요. 이름처럼 가볍게 올라가는데 커버력은 미쳤어요;; 다크서클 심한 편인데 이거 하나로 다 가려짐. 스펀지로 블렌딩하니까 경계도 안 지고 자연스러워요. 건성분들 강추! 👍","u":"네이버 페이 구매자","d":"2025-12-19 11:32:00","r":0,"p":[]},{"i":2485,"s":5,"t":"와 이거 진짜 물건이네요.. 컨실러 쓸 때 브러쉬 따로 꺼내기 귀찮아서 손으로 대충 발랐는데, 이건 스펀지 팁 달려있어서 그냥 톡톡 두드리면 끝나요. 커버력도 상타치고 무엇보다 손에 안 묻어서 너무 편함. 다크서클 가리기 딱입니다.","u":"네이버 페이 구매자","d":"2025-12-19 11:30:00","r":0,"p":[]},{"i":2484,"s":5,"t":"유튜브에서 하도 좋다길래 궁금해서 사봄.. 일단 스펀지 팁이 편하긴 한데 양 조절 잘 해야 할 것 같아요. 푹 찍으면 너무 많이 나와서.. 소량만 찍어서 내장 팁으로 펴바르면 피부 표현 진짜 예쁘게 됨. 모공 커버도 잘 되고 요철 부각 없어서 좋아요. N사 컨실러 쓰다가 갈아탔는데 이게 더 얇게 발려서 맘에 듭니다. 추천해요!","u":"네이버 페이 구매자","d":"2025-12-19 10:16:00","r":0,"p":[]},{"i":2483,"s":5,"t":"배송 빠르고 좋아요. 스펀지 있어서 편하고 커버력도 상타치ㅎㅎ 지속력도 좋아서 아침에 하고 나가면 저녁까지 멀쩡해요. 파우치 부피 줄이기 딱 좋은 아이템입니당 잘 쓸게요~","u":"네이버 페이 구매자","d":"2025-12-19 09:06:00","r":0,"p":[]},{"i":2482,"s":4,"t":"다크서클이 진짜 심해서 웬만한 컨실러로는 커버가 안 되는데 탐뷰티꺼 평 좋길래 사봤어요. 일단 커버력은 인정.. 얇게 발리는데 잡티랑 다크는 확실하게 가려줍니다. 스펀지로 톡톡 두드리니까 경계선 안 생기고 자연스럽게 블렌딩되네요. 건성인데 기초 탄탄하게 하고 바르니까 눈가 끼임도 거의 없었어요ㅎ 세일할 때 하나 더 쟁여놔야겠음.","u":"네이버 페이 구매자","d":"2025-12-19 08:23:00","r":0,"p":[]},{"i":2481,"s":5,"t":"수부지 피부라 컨실러 잘못 쓰면 시간 지나서 다 뜨고 난리나는데 이건 밀착력이 진짜 좋네요. 이름처럼 가볍게 올라가는데 픽싱되면 딱 달라붙어서 안 움직여요. 유분기 올라와도 더럽게 무너지는 게 아니라서 맘에 듭니당. 스펀지 팁 내장된 게 위생은 살짝 걱정되긴 하는데 톡톡 두드리면 블렌딩이 너무 잘 돼서 포기 못할 듯.. 21호 쓰는데 컬러도 화사하고 예뻐요!","u":"네이버 페이 구매자","d":"2025-12-19 08:12:00","r":0,"p":[]},{"i":2480,"s":4,"t":"와 이거 진짜 물건이네요.. 광고 보고 반신반의하면서 샀는데 스펀지 팁 달린 게 신의 한 수입니다ㅎ 밖에서 수정화장할 때 브러쉬 따로 안 챙겨도 되고 손에 안 묻혀도 돼서 너무 편해요. 커버력도 꽤 높은 편이라 다크서클 싹 가려지는데 텁텁하지 않게 올라가서 좋았어요. 지속력도 아침에 바르고 점심 먹고 봐도 그대로라 놀랐음... 다 쓰면 재구매 할 것 같아요.","u":"네이버 페이 구매자","d":"2025-12-19 08:02:00","r":0,"p":[]},{"i":2479,"s":5,"t":"탐뷰티 처음 써보는데 물건이네요.. 스펀지가 진짜 요물임 똥손인데도 블렌딩 쉽게 됨. 트러블 자국 많은 편인데 소량으로도 커버 잘 되고 답답한 느낌 없음. 세일할 때 쟁여야겠음 👍","u":"네이버 페이 구매자","d":"2025-12-19 03:30:00","r":0,"p":[]},{"i":2478,"s":4,"t":"건성이라 뜨지 않을까 걱정했는데 기초만 잘해주면 촥 달라붙음. 얇게 발리는데 커버는 확실해서 컨실러 유목민 여기서 정착함. 가지고 다니면서 수정하기도 편하고 걍 좋음 사세요","u":"네이버 페이 구매자","d":"2025-12-19 02:43:00","r":0,"p":[]},{"i":2477,"s":5,"t":"유튜브 보다가 영업당해서 샀는데 색상이 진짜 이쁘게 빠짐. 21호 쓰는데 너무 밝지도 않고 잡티 딱 가려주는 컬러임. 내장 스펀지로 경계 풀어주면 티 하나도 안 나고 자연스러움. 재구매각","u":"네이버 페이 구매자","d":"2025-12-19 00:34:00","r":0,"p":[]},{"i":2476,"s":5,"t":"지성 피부라 유분기 폭발하는데 이건 지속력 미쳤음;; 점심시간 지나도 코 옆 끼임 거의 없고 짱짱하게 붙어있음. 땀나도 잘 안 지워져서 여름에 쓰기 딱일 듯. 밀착력 굿","u":"네이버 페이 구매자","d":"2025-12-18 23:11:00","r":0,"p":[]},{"i":2475,"s":4,"t":"스펀지팁 달려있는 거 보고 바로 결제함ㅋㅋ 손에 묻히는 거 싫어하는데 이건 걍 뚜껑 열고 톡톡하면 끝이라 개편함. 커버력도 기대 안 했는데 다크서클 싹 가려져서 놀람. 아침에 시간 없을 때 최고임","u":"네이버 페이 구매자","d":"2025-12-18 22:19:00","r":0,"p":[]},{"i":2474,"s":5,"t":"다크서클이 심해서 샀는데 두껍게 안 발리고 얇게 커버돼서 좋아요. 스펀지로 펴 바르니까 경계도 안 생기고 자연스럽네요. 지속력도 좋아서 아침에 바르고 나가면 저녁까지 멀쩡합니다👍","u":"네이버 페이 구매자","d":"2025-12-18 14:47:00","r":0,"p":[]},{"i":2473,"s":5,"t":"커버력은 진짜 좋은데 스펀지 위생 관리가 좀 신경 쓰이긴 해요. 그래도 손에 안 묻는 편안함을 포기 못해서 재구매각.. 붉은 기랑 트러블 자국 싹 가려줘서 피부 좋아 보인다는 말 들었어요ㅎ","u":"네이버 페이 구매자","d":"2025-12-18 13:32:00","r":0,"p":[]},{"i":2472,"s":5,"t":"지복합성이라 오후 되면 유분 폭발하는데 이건 픽싱이 빨라서 그런지 오래 버티네요! 땀 많이 흘린 날에도 수정 화장 거의 안 했어요. 스펀지로 두드리면 밀착력 더 좋아지는 느낌이라 계속 쓸 것 같아요.","u":"네이버 페이 구매자","d":"2025-12-18 12:28:00","r":0,"p":[]},{"i":2471,"s":5,"t":"건성이라 컨실러 잘못 쓰면 눈가 주름에 끼는데 이건 얇게 발려서 괜찮아요. 이름처럼 가볍게 올라가는데 커버력은 확실하네요. 오후 돼도 다크닝 없이 유지되는 편이라 만족하며 쓰는 중입니다.","u":"네이버 페이 구매자","d":"2025-12-18 11:47:00","r":0,"p":[]},{"i":2470,"s":4,"t":"스펀지 팁이 내장되어 있어서 따로 브러쉬 안 챙겨도 되는 게 진짜 편해요. 다크서클 쪽에 콕 찍고 톡톡 두드리면 끝이라 아침에 시간 단축됨.. 커버력도 중상 정도라 웬만한 잡티는 다 가려지네요.","u":"네이버 페이 구매자","d":"2025-12-18 11:21:00","r":0,"p":[]},{"i":2469,"s":5,"t":"21호 쿨톤인데 컬러도 너무 노랗지 않고 화사하게 잘 빠졌네요. 보통 커버력 좋으면 텁텁해 보이기 쉬운데 이건 얇게 발리면서 가릴 건 다 가려줘요. 브러쉬 챙기기 귀찮은 보부상들한테 완전 강추합니다 ㅎㅎ","u":"네이버 페이 구매자","d":"2025-12-18 10:46:00","r":0,"p":[]},{"i":2468,"s":5,"t":"탐뷰티 처음 들어보는 브랜드라 반신반의하면서 샀는데 기대 이상이에요. 홍조랑 트러블 자국 많은 편인데 두껍지 않게 커버되면서 피부 표현이 예쁘게 돼요 ㅠㅠ 내장 스펀지가 너무 딱딱하지도 않고 탄력 있어서 밀착력 높여주는 듯!","u":"네이버 페이 구매자","d":"2025-12-18 09:51:00","r":0,"p":[]},{"i":2467,"s":5,"t":"수부지 피부라 유분 폭발하면 베이스 다 무너지는데 이건 롱웨어라 그런지 지속력 미쳤음.. 땀 흘려도 안 지워지고 피부에 딱 붙어있어요. 수정 화장할 때도 스펀지 팁으로 살살 펴주면 끝이라 파우치 필수템 됐어요.","u":"네이버 페이 구매자","d":"2025-12-18 08:54:00","r":0,"p":[]},{"i":2466,"s":5,"t":"건성이라 매트한 컨실러 쓰면 눈가 주름에 끼이고 난리 나는데, 더 클라우드라는 이름처럼 가볍게 밀착돼서 안 떠요. 스펀지로 톡톡 두드려주면 블렌딩도 자연스럽게 잘 되고 무엇보다 오후 돼도 다크닝 없이 화사하게 유지돼서 만족해요.","u":"네이버 페이 구매자","d":"2025-12-18 08:53:00","r":0,"p":[]},{"i":2465,"s":4,"t":"손에 컨실러 묻히는 거 싫어서 샀는데 스펀지 팁 내장된 게 진짜 신의 한 수네요. 다크서클 부위에 콕 찍고 스펀지로 펴 바르니까 도구 따로 안 챙겨도 돼서 아침에 시간 단축 대박이에요. 커버력도 짱짱해서 얇게 발라도 잡티 순삭됨!","u":"네이버 페이 구매자","d":"2025-12-18 07:27:00","r":0,"p":[]},{"i":2464,"s":5,"t":"일단 손에 뭐 안 묻히고 화장할 수 있다는 게 최대 장점 ㅠㅠ 바쁜 아침에 후다닥 다크서클이랑 코 옆 붉은기 잡기 최고예요. 밀착력이 좋아서 마스크 써도 잘 안 묻어납니다. 색상은 옐로우 베이스라 붉은기 잡기에 최적화된 느낌? 고민하지 말고 사세요 ㅋㅋ","u":"네이버 페이 구매자","d":"2025-12-18 06:27:00","r":0,"p":[]},{"i":2463,"s":5,"t":"이름이 클라우드라 그런가 확실히 가볍게 올라가는 느낌이 좋네요. 보통 커버력 좋으면 텁텁하기 마련인데 이건 얇게 밀착되면서 가려질 건 다 가려져요. 건성이라 눈가 건조하면 쩍쩍 갈라지는데 기초 탄탄히 하고 바르니까 뜨는 거 없이 매끈해요. 내장 팁이 생각보다 쫀쫀해서 밀착력을 높여주는 듯? 세일할 때 쟁여야겠어요","u":"네이버 페이 구매자","d":"2025-12-18 06:22:00","r":0,"p":[]},{"i":2462,"s":5,"t":"여드름 흉터랑 붉은기 때문에 웬만한 컨실러 다 써봤는데 커버력 상위권이에요. 스펀지 팁이라 양 조절 못하면 두껍게 발릴 수 있으니 살짝만 찍어서 펴바르는 게 꿀팁! 21호 쓰는데 1호 컬러 화사하게 잘 맞아요. 잡티 위에 콕 찍어두고 조금 이따가 경계 풀어주면 완벽하게 가려집니다.. 재구매 의사 있어요","u":"네이버 페이 구매자","d":"2025-12-18 04:46:00","r":0,"p":[]},{"i":2461,"s":5,"t":"지성 피부라 오후만 되면 유분 올라와서 컨실러 다 지워지는데 이건 지속력 인정합니다 👍 땀 많이 흘리는 편인데도 저녁까지 다크닝 없이 잘 붙어있어요. 제형은 처음엔 촉촉한가 싶은데 픽싱되면 딱 고정되는 스타일이라 바르고 나서 바로 블렌딩해줘야 해요. 커버력은 좋은데 답답한 느낌 없어서 이번 여름은 이걸로 정착할 듯!","u":"네이버 페이 구매자","d":"2025-12-18 04:02:00","r":0,"p":[]},{"i":2460,"s":5,"t":"와.. 탐뷰티 광고보고 반신반의하면서 샀는데 내장된 스펀지 팁이 진짜 물건이네요 ㅋㅋ 다크서클 가릴 때 브러쉬 따로 챙기기 귀찮아서 손으로 톡톡하다가 맨날 지문 자국 남았는데.. 이건 그냥 슥 긋고 내장 스펀지로 두드리면 끝이라 너무 편해요! 커버력도 중상 이상이고 얇게 올라가서 눈가 주름 끼임도 적은 편입니다. 수정화장용으로 파우치에 넣고 다니기 딱 좋음","u":"네이버 페이 구매자","d":"2025-12-18 03:59:00","r":0,"p":[]},{"i":2459,"s":5,"t":"21호 웜톤인데 컬러가 화사하게 잘 빠졌어요. 너무 노랗지 않아서 잡티 커버는 물론이고 하이라이터 대용으로 써도 됨. 무엇보다 스펀지 일체형이라 파우치 부피 줄어서 너무 좋음.. 수정화장용으로 강추합니다 👍","u":"네이버 페이 구매자","d":"2025-12-18 02:53:00","r":0,"p":[]},{"i":2458,"s":5,"t":"탐뷰티 신상이라 속는 셈 치고 사봤는데 기대 이상이에요. 턱 쪽에 트러블 자국 많은데 스펀지 팁으로 콕콕 찍어서 두드리니까 감쪽같이 사라짐;; 밀착력이 좋아서 그런지 마스크 껴도 잘 안 벗겨져요. 인생템 찾은 듯.","u":"네이버 페이 구매자","d":"2025-12-17 21:48:00","r":0,"p":[]},{"i":2457,"s":5,"t":"다크서클이 푸른 편이라 커버력 중요하게 보는데 얇은데 확실하게 가려짐! 스펀지 어플리케이터가 진짜 신의 한 수.. 손에 안 묻히고 슥슥 바르니까 위생적이고 편해요. 눈가 주름 끼임도 거의 없어서 건성분들도 쓰기 좋을 듯.","u":"네이버 페이 구매자","d":"2025-12-17 21:15:00","r":0,"p":[]},{"i":2456,"s":4,"t":"수부지 피부인데 지속력 인정합니다. 오후 되면 유분 올라와서 다크서클 다시 보이는데 이건 퇴근할 때까지 짱짱하게 버티네요. 픽싱이 빨라서 바르고 바로 내장 스펀지로 펴주면 딱붙임. 재구매 의사 있음.","u":"네이버 페이 구매자","d":"2025-12-17 20:16:00","r":0,"p":[]},{"i":2455,"s":5,"t":"와 이거 진짜 물건이네요.. 스펀지팁 달려있는 게 이렇게 편할 줄 몰랐어요. 브러쉬 따로 안 꺼내고 걍 톡톡 두드리면 블렌딩까지 끝남. 아침에 바쁠 때 최고임ㅠ 커버력도 중상 이상이라 잡티 싹 가려져요.","u":"네이버 페이 구매자","d":"2025-12-17 19:56:00","r":0,"p":[]},{"i":2454,"s":5,"t":"잡티 커버용으로 샀어요. 콕 찍고 내장 스펀지로 경계 풀어주니까 똥손도 쉽게 커버 가능해요ㅋㅋ 지속력도 좋아서 아침에 하고 나가면 저녁까지 거의 그대로임. 세일할 때 쟁여두려고요.","u":"네이버 페이 구매자","d":"2025-12-17 19:25:00","r":0,"p":[]},{"i":2453,"s":4,"t":"21호 웜톤인데 컬러가 너무 둥둥 뜨지 않고 자연스럽게 맞아요. 내돈내산 컨실러 중에 최근 젤 만족템! 스펀지가 내장된 게 신의 한 수네요 손에 안 묻히고 슥슥 펴 바르기 짱 편함. 아침에 바쁠 때 휘뚜루마뚜루 쓰기 좋아요 👍","u":"네이버 페이 구매자","d":"2025-12-17 19:17:00","r":0,"p":[]},{"i":2452,"s":4,"t":"커버력은 확실히 좋은데 극건성인 저한테는 마무리감이 좀 매트하게 느껴졌어요. 기초 탄탄하게 안 하면 눈가 주름 끼임 살짝 있을 수 있음. 여름에 쓰기엔 좋을 것 같은데 지금 날씨엔 기초 빡세게 해야 함.. 그래도 스펀지로 톡톡 두드리면 블렌딩은 쉬워요.","u":"네이버 페이 구매자","d":"2025-12-17 19:06:00","r":0,"p":[]},{"i":2451,"s":4,"t":"탐뷰티 처음 들어보는 브랜드라 반신반의하면서 샀는데 기대 이상이에요. 제가 지성이라 오후 되면 베이스 다 무너지는데 이건 픽싱이 빨라서 오래 가네요. 다크서클 커버도 잘 되고 밀착력 굿. 재구매 의사 있어요.","u":"네이버 페이 구매자","d":"2025-12-17 15:43:00","r":0,"p":[]},{"i":2450,"s":5,"t":"스펀지 팁 달려있는 거 보고 편해 보여서 샀는데 진짜 편해요. 따로 브러쉬 안 챙겨도 돼서 수정 화장용으로 딱입니다. 커버력도 나쁘지 않고 다크서클 가리기 좋아요. 다만 양 조절은 좀 신경 써야 할 듯요.","u":"네이버 페이 구매자","d":"2025-12-17 14:56:00","r":0,"p":[]},{"i":2449,"s":5,"t":"친구 추천으로 샀는데 지속력 진짜 좋네요. 아침에 바르고 나가서 저녁까지 수정 화장 거의 안 했어요. 스펀지가 내장돼 있어서 휴대하기도 간편하고 위생적이라 맘에 듭니다.","u":"네이버 페이 구매자","d":"2025-12-17 14:53:00","r":0,"p":[]},{"i":2448,"s":5,"t":"21호 쿨톤인데 컬러 잘 맞아요. 눈가 주름 끼임 때문에 컨실러 잘 안 쓰는데 이건 촉촉하게 발리면서 마무리는 깔끔해서 만족. 파데 대신 이거 하나로 베이스 끝내도 될 듯.","u":"네이버 페이 구매자","d":"2025-12-17 14:04:00","r":0,"p":[]},{"i":2447,"s":5,"t":"쓰던 컨실러 다 써서 탐뷰티꺼 사봤는데 기대 이상! 스펀지 어플리케이터가 진짜 신의 한 수예요. 똥손인데도 블렌딩하기 쉽고 잡티 커버 완벽하게 됨. 재구매 각.","u":"네이버 페이 구매자","d":"2025-12-17 14:02:00","r":0,"p":[]},{"i":2446,"s":5,"t":"수부지 피부라 오후 되면 유분 폭발하는데 이건 짱짱하게 붙어있네요. 땀 흘려도 안 무너지는 거 보고 놀랐음.. 스펀지로 두드리니까 모공도 잘 가려지고 밀착력 대박입니다 👍","u":"네이버 페이 구매자","d":"2025-12-17 13:27:00","r":0,"p":[]},{"i":2445,"s":5,"t":"스펀지 팁이 달려있어서 손에 안 묻히고 쓱쓱 바르기 너무 편해요. 아침에 시간 없을 때 꿀템임. 커버력도 좋은데 두껍지 않아서 다크서클 가리기 딱 좋아요.","u":"네이버 페이 구매자","d":"2025-12-17 13:17:00","r":0,"p":[]},{"i":2444,"s":5,"t":"19-21호 쿨톤인데 컬러가 누렇지 않고 상아빛으로 예쁘게 빠졌어요! 컨실러 유목민이었는데 스펀지로 두드리니까 경계 안 지고 자연스럽게 커버됨. 무엇보다 마스크 쓰고 땀나도 잘 안 벗겨져서 좋아요👍 세일할 때 쟁여둘 예정.","u":"네이버 페이 구매자","d":"2025-12-17 13:15:00","r":0,"p":[]},{"i":2443,"s":5,"t":"스펀지 팁이라 양 조절 못하면 두껍게 발릴 수 있는데, 소량으로 톡톡하면 깐달걀 가능ㅇㅇ 손 안 대고 슥슥 바를 수 있는 게 최대 장점인 듯해요. 홍조랑 잡티 커버는 확실히 잘 돼요. 지속력도 아침에 바르고 나가서 저녁까지 수정 딱히 안 해도 괜찮았음.","u":"네이버 페이 구매자","d":"2025-12-17 12:18:00","r":0,"p":[]},{"i":2442,"s":5,"t":"탐뷰티 베이스 맛집이라길래 사봤는데 기대 이상이네요. 일단 밀착력이 좋아서 피부에 촥 붙는 느낌이 맘에 들어요. 트러블 자국 가릴 때 뒤에 달린 스펀지로 꾹꾹 눌러주면 순삭됨. 땀 흘려도 지저분하게 안 무너져서 여름까지 잘 쓸 것 같아요. 재구매 의사 100%","u":"네이버 페이 구매자","d":"2025-12-17 07:18:00","r":0,"p":[]},{"i":2441,"s":5,"t":"요즘 잠을 못 자서 다크서클 장난 아닌데 커버력 미쳤어요;; 보통 커버력 좋으면 텁텁하게 발리는데 이건 가볍게 올라가는 느낌? 내장 스펀지로 톡톡 두드리니까 주름 끼임도 덜하고 블렌딩이 쉬워서 곰손들한테 추천해요. 건성 김미연인데 기초 탄탄히 하고 바르니까 건조함 딱히 없었어요.","u":"네이버 페이 구매자","d":"2025-12-17 06:05:00","r":0,"p":[]},{"i":2440,"s":5,"t":"스펀지 팁이 진짜 신의 한 수... 컨실러 브러쉬 따로 챙기기 귀찮은데 이거 하나로 해결돼서 밖에서 수정화장할 때 짱 편해요. 수부지라 오후만 되면 유분기 폭발하는데 이건 지속력도 꽤 버티는 편? 다크서클 커버도 잘되고 밀착력 인정합니당. 21호 쓰는데 컬러도 자연스러움.","u":"네이버 페이 구매자","d":"2025-12-17 06:03:00","r":0,"p":[]},{"i":2439,"s":5,"t":"23호 웜톤인데 네추럴 베이지 컬러 자연스럽게 잘 어우러져요. 스펀지가 처음엔 좀 단단한가 싶었는데 몇 번 쓰니까 부드러워짐. 바쁜 아침에 그냥 슥 긋고 뒤로 톡톡하면 끝이라 시간 단축 꿀템입니다 ㅋㅋ 두껍게 안 발리고 얇게 올라가서 답답한 느낌 없어요.","u":"네이버 페이 구매자","d":"2025-12-17 06:02:00","r":0,"p":[]},{"i":2438,"s":5,"t":"배송 빠르고 포장 꼼꼼해요. 커버력 좋다고 해서 샀는데 잡티 잘 가려지네요. 스펀지가 생각보다 쫀쫀해서 두드릴수록 밀착 잘 됩니다. 잘 쓸게요.","u":"네이버 페이 구매자","d":"2025-12-17 03:35:00","r":0,"p":[]},{"i":2437,"s":5,"t":"지성이라 오후만 되면 베이스 다 녹아내리는데 이건 롱웨어라 그런지 저녁까지 짱짱해요. 손에 뭐 묻히는 거 싫어해서 스펀지 내장된 거 보고 샀는데 위생적이고 블렌딩도 자연스럽게 잘 됨. 다만 양 조절 필수! 콕 찍어서 펴 바르면 커버 끝나요. 쿨톤 21호 기준 1호 화사하게 잘 맞습니다 👍","u":"네이버 페이 구매자","d":"2025-12-17 01:52:00","r":0,"p":[]},{"i":2436,"s":4,"t":"21호 건성입니다. 보통 고커버 컨실러는 너무 건조해서 뜨는데 이건 '클라우드' 이름값 하네요. 촉촉하게 발리는데 마무리는 세미매트해서 딱 좋아요. 내장 스펀지로 톡톡 두드리면 밀착 미쳤음;; 다크서클보다는 붉은 여드름 자국 가리는데 짱이에요. 지속력도 땀 흘려도 그대로라 여름까지 쭉 쓸 듯. 탐뷰티 처음 들어봤는데 물건이네요.","u":"네이버 페이 구매자","d":"2025-12-17 01:24:00","r":0,"p":[]},{"i":2435,"s":5,"t":"스펀지 팁 달려있어서 밖에서 수정할 때 진짜 편해요. 따로 브러쉬나 퍼프 안 챙겨도 돼서 파우치 짐 줄었음. 다크서클 커버력도 기대 이상이고 픽싱되면 하루 종일 안 무너져서 만족합니다. 재구매 의사 있어요.","u":"네이버 페이 구매자","d":"2025-12-16 23:45:00","r":0,"p":[]},{"i":2434,"s":5,"t":"친구 추천으로 샀는데 기대 이상임. 뭉침 없이 얇게 발리는데 고정력 대박... 피부 표현 깔끔하게 되고 오래가서 정착할 예정.","u":"네이버 페이 구매자","d":"2025-12-16 21:09:00","r":0,"p":[]},{"i":2433,"s":5,"t":"브러쉬 따로 안 챙겨도 돼서 수정 화장할 때 진짜 편함. 톡 찍고 슥슥 문지르면 끝. 지속력도 좋아서 여름에 쓰기 좋을 듯!","u":"네이버 페이 구매자","d":"2025-12-16 16:47:00","r":0,"p":[]},{"i":2432,"s":5,"t":"다크서클 심해서 샀는데 끼임 없이 얇게 잘 가려짐. 내장 스펀지로 펴주면 경계 안 지고 자연스러움. 색상도 이쁘게 잘 빠짐.","u":"네이버 페이 구매자","d":"2025-12-16 16:29:00","r":0,"p":[]},{"i":2431,"s":5,"t":"수부지인데 오후에도 안 무너지고 짱짱함. 땀 좀 흘렸는데도 그대로라 놀랐음ㅋㅋ 커버력은 중상 정도? 웬만한 잡티는 다 가려짐.","u":"네이버 페이 구매자","d":"2025-12-16 16:15:00","r":0,"p":[]},{"i":2430,"s":5,"t":"스펀지 팁 달린 게 진짜 신의 한 수... 손에 안 묻히고 톡톡 두드리면 끝이라 아침에 개편함. 밀착력 좋아서 마스크 써도 잘 안 묻어남.","u":"네이버 페이 구매자","d":"2025-12-16 15:47:00","r":0,"p":[]},{"i":2429,"s":5,"t":"탐뷰티 처음 들어보는 브랜드라 반신반의하면서 샀는데 기대 이상이에요. 스펀지 팁이 생각보다 쫀쫀해서 블렌딩 잘 됨! 여행 갈 때 브러쉬 챙기기 귀찮은데 이거 하나면 될 것 같아요.","u":"네이버 페이 구매자","d":"2025-12-16 14:29:00","r":0,"p":[]},{"i":2428,"s":5,"t":"이름처럼 가볍게 발리는데 잡티는 싹 가려줘서 요즘 파데프리 할 때 이거만 써요ㅋㅋㅋ 스펀지 내장된 게 진짜 편하고 위생적인 느낌? 다 쓰면 또 살 거예요 👍","u":"네이버 페이 구매자","d":"2025-12-16 13:45:00","r":0,"p":[]},{"i":2427,"s":5,"t":"파워 지성이라 오후 되면 컨실러 다 녹는데 이건 짱짱하게 버티네요? 땀 많이 흘리는 편인데도 유지력 무엇.. 스펀지로 톡톡 두드려주면 블렌딩도 쉬워서 곰손들도 쓰기 편할 듯요.","u":"네이버 페이 구매자","d":"2025-12-16 10:33:00","r":0,"p":[]},{"i":2426,"s":4,"t":"21호 쿨톤인데 컬러 자연스럽게 잘 빠졌네요. 제가 눈가 주름이 좀 있어서 컨실러 잘못 쓰면 끼이는데 이건 얇게 밀착돼서 좋아요. 다크서클 커버용으로 강추합니다.","u":"네이버 페이 구매자","d":"2025-12-16 08:42:00","r":0,"p":[]},{"i":2425,"s":5,"t":"스펀지 팁 달려있는 거 진짜 신의 한 수.. 손에 묻히기 싫어서 샀는데 너무 편해요ㅠㅠ 다크서클 슥슥 긋고 두드리면 끝이라 아침에 시간 단축 대박임. 커버력도 중상 이상!!","u":"네이버 페이 구매자","d":"2025-12-16 00:01:00","r":0,"p":[]}]};
